question:
You are given a question that requires some input and output variables as follows:

Given a sequence of numbers, how can we obtain the sequence in either normal or reverse order based on a specified condition?

The input and output requirements are as follows:

Input:
  `elements` (list): A list of elements to be added to the list. Each element can be of any type.
  `reverse` (bool): A boolean indicating whether to return the list in reverse order. Default is `False`.

Output:
  `return` (list): A list of elements in the specified order (either normal or reversed).

Given the following output:

[82, True, 28.0, True]

Can you predict a feasible input? Please reason and put your final answer in the form of a JSON object enclosed in triple angle brackets, like this <<<JSON object>>>, even if the there is only one input variable, with keys strictly matching the input variables' names as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

# import necessary packages
import random

# all class and function definitions in the code file, if any
class EmptyList(Exception):
    def __init__(self, msg):
        self.message = msg

class NoSuchElementException(Exception):
    def __init__(self, msg):
        self.message = msg

class List:
    class Cell:
        def __init__(self, value, next_cell, prev_cell):
            self.value = value
            self.next = next_cell
            self.prev = prev_cell

    def __init__(self):
        self.head = None
        self.tail = None

    def is_empty(self):
        return self.head is None and self.tail is None

    def cons(self, value):
        if self.head is None:
            self.head = self.tail = List.Cell(value, None, None)
        else:
            self.head = List.Cell(value, self.head, None)
            self.head.next.prev = self.head

    def get_listiterator(self, reverse=False):
        return List.ListIterator(self, reverse)

    class ListIterator:
        def __init__(self, list, reverse=False):
            self.list = list
            self.current = list.head if not reverse else list.tail

        def hasNext(self):
            return self.current.next is not None

        def next(self):
            if self.hasNext():
                self.current = self.current.next
                return self.current.value
            else:
                raise NoSuchElementException('there is no next item')

        def hasPrevious(self):
            return self.current.prev is not None

        def previous(self):
            if self.hasPrevious():
                self.current = self.current.prev
                return self.current.value
            else:
                raise NoSuchElementException('there is no previous item')

        def add(self, value, before=True):
            if self.current is None:
                self.list.cons(value)
            else:
                if self.hasPrevious():
                    if before:
                        new_cell = List.Cell(value, self.current, self.current.prev)
                        self.current.prev.next = new_cell
                        self.current.prev = new_cell
                    else:
                        if self.hasNext():
                            new_cell = List.Cell(value, self.current.next, self.current)
                            self.current.next.prev = new_cell
                            self.current.next = new_cell
                        else:
                            new_cell = List.Cell(value, None, self.current)
                            self.list.tail = new_cell
                            self.current.next = new_cell
                            self.next()
                else:
                    new_cell = List.Cell(value, self.current, None)
                    self.list.head = new_cell
                    self.current.prev = new_cell

        def remove(self):
            if self.hasPrevious():
                if self.hasNext():
                    self.current.next.prev = self.current.prev.next
                    self.current.prev.next = self.current.next.prev
                    self.current = self.current.next
                else:
                    self.current.prev.next = None
                    self.list.tail = self.current.prev
                    self.current = self.current.prev
            elif self.hasNext():
                self.current.next.prev = None
                self.list.head = self.current.next
                self.current = self.current.next
            else:
                self.current = None

# main function
def main_solution(elements, reverse=False):
    """
    Creates a list from the given elements and returns the list in the specified order.

    :param elements: A list of elements to be added to the list.
    :type elements: list
    :param reverse: A boolean indicating whether to return the list in reverse order.
    :type reverse: bool
    :return: A list of elements in the specified order.
    :rtype: list
    """
    lst = List()
    for element in elements:
        lst.cons(element)

    iterator = lst.get_listiterator(reverse)
    result = []
    try:
        while True:
            result.append(iterator.next())
    except NoSuchElementException:
        pass

    return result

