def dfs(matrix, i, j, row, col):
    length = 1
    matrix[i][j] = 0
    if (i + 1 < row) and (matrix[i + 1][j] == 1):
        length += dfs(matrix, i + 1, j, row, col)
    if (i - 1 >= 0) and (matrix[i - 1][j] == 1):
        length += dfs(matrix, i - 1, j, row, col)
    if (j + 1 < col) and (matrix[i][j + 1] == 1):
        length += dfs(matrix, i, j + 1, row, col)
    if (j - 1 >= 0) and (matrix[i][j - 1] == 1):
        length += dfs(matrix, i, j - 1, row, col)
    return length

