# import necessary packages
import math

# all class and function definitions in the code file, if any
def process_block(str_int):
    sign = 1
    if str_int[0] == "-":
        sign = -1
    return sign * int(str_int[1:])

def construct_edges(chroms):
    edge_list = []
    for chr in chroms:
        for i in range(len(chr)):
            fst = chr[i - 1]
            if fst < 0:
                src = start_node(-fst)
            else:
                src = end_node(fst)
            snd = chr[i]
            if snd < 0:
                dest = end_node(-snd)
            else:
                dest = start_node(snd)
            edge_list.append((src, dest))
    return edge_list

def start_node(x):
    return 2 * x - 1

def end_node(x):
    return 2 * x

# main function
def main_solution(signed_permutation):
    # Convert the signed permutation string into a list of integers
    chroms = [[process_block(x) for x in y.split()] for y in signed_permutation.strip().lstrip("(").rstrip(")").split(")(")]

    # Construct the edges from the chromosomes
    edges = construct_edges(chroms)

    # Convert the edges to a JSON serializable format
    edge_list = [f"({src},{dest})" for src, dest in edges]

    # Return the edges as a comma-separated string
    return ", ".join(edge_list)
