    custom_objects = [Custom(value, rank) for value, rank in zip(values, ranks)]

    # Simulate the reduce operation
    result = custom_objects[0]
    for obj in custom_objects[1:]:
        result = minLoc(result, obj)

    # Convert the result to JSON serializable output
    return {"min_value": result.value, "min_rank": result.rank}
