# import necessary packages
from collections import defaultdict

# all class and function definitions in the code file, if any
def dfs(adj, visited, u):
    stack = [u]
    count = 0

    while stack:
        s = stack.pop()

        if not visited[s]:
            count += 1
            visited[s] = True

        for i in adj[s]:
            if not visited[i]:
                stack.append(i)

    return count

# main function
def main_solution(X, friendships):
    adj = defaultdict(list)
    visited = defaultdict(bool)

    for u, v in friendships:
        adj[u].append(v)
        adj[v].append(u)

    adj[X].sort()

    maxi = 0
    ch = "A"

    visited[X] = True

    for i in adj[X]:
        if not visited[i]:
            ans = dfs(adj, visited, i)
            if ans > maxi:
                maxi = ans
                ch = i
            elif ans == maxi and i < ch:
                ch = i

    return {"friend_name": ch, "view_count": maxi}
