# import necessary packages
from decimal import Decimal

# all class and function definitions in the code file, if any
class Pitch:
    PITCHES = { 'A': 0, 'B': 2, 'C': 3, 'D': 5, 'E': 7, 'F': 8, 'G': 10, 'R': -1 }
    ACCIDENTALS = { '#': +1, 'b': -1, '?': 0 }

    def __init__(self, pitch, accidental, octave):
        self._pitch = Pitch.PITCHES[pitch]
        self._accidental = Pitch.ACCIDENTALS[accidental]
        self._octave = octave

    def freq(self):
        freq_A2 = Decimal(110.0)
        if self._pitch != Pitch.PITCHES['R']:
            return freq_A2 * Decimal(2**((Decimal(self._pitch + self._accidental + (12.0 * self._octave))) / Decimal(12.0)))
        else:
            return -1

# main function
def main_solution(pitch, accidental, octave):
    # Convert JSON serializable inputs to the original input variables
    pitch_obj = Pitch(pitch, accidental, octave)
    # Calculate the frequency
    frequency = pitch_obj.freq()
    # Convert the result to a JSON serializable output
    return float(frequency)
