You are given a question that requires some input and output variables as follows:

In the context of information retrieval, various metrics are used to evaluate the performance of retrieval systems. Given a set of binary results and their corresponding ground truth numbers, what is the average value of the specified metric across all results, and what are the individual metric values for each result?

The input and output requirements are as follows:

Input:
  `data` (list of tuples): A list of tuples where each tuple contains a list of binary values (0 or 1) and an integer representing the total ground truth number.
  `metric` (string): A string specifying the metric to compute. Possible values are "precision", "recall", "f1", "mrr", "map".

Output:
  `return` (dictionary): A dictionary containing the computed metric value and a list of individual metric values for each tuple in the data.
    - `average_metric` (float): The average value of the specified metric across all tuples in the data.
    - `individual_metrics` (list of floats): A list of metric values for each tuple in the data.

Given the following output:

{'average_metric': np.float64(0.5646031746031746), 'individual_metrics': [np.float64(0.5555555555555556), np.float64(0.3333333333333333), np.float64(0.6), np.float64(0.5), np.float64(0.5714285714285714), np.float64(0.5), np.float64(1.0), np.float64(0.2857142857142857), np.float64(0.5), np.float64(0.8)]}

Can you predict a feasible input? Please reason and put your final answer in the form of a JSON object enclosed in triple angle brackets, like this <<<JSON object>>>, even if the there is only one input variable, with keys strictly matching the input variables' names as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

# import necessary packages
import numpy as np

# all class and function definitions in the code file, if any
class InformationRetrievalMetric:
    @staticmethod
    def precision(data):
        if type(data) != list and type(data) != tuple:
            raise Exception("the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple")

        if len(data) == 0:
            return 0.0, [0.0]
        if type(data) == tuple:
            if data[1] == 0:
                return 0.0, [0.0]
            else:
                precision = np.mean(data[0])
                return precision, [precision]

        if type(data) == list:
            separate_result = []
            for sub_list, total_num in data:
                if total_num == 0:
                    precision = 0
                else:
                    precision = np.mean(sub_list)

                separate_result.append(precision)
            return np.mean(separate_result), separate_result

    @staticmethod
    def recall(data):
        if type(data) != list and type(data) != tuple:
            raise Exception("the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple")

        if len(data) == 0:
            return 0.0, [0.0]
        if type(data) == tuple:
            if data[1] == 0:
                return 0.0, [0.0]
            else:
                recall = np.sum(data[0]) / data[1]
                return recall, [recall]

        if type(data) == list:
            separate_result = []
            for sub_list, total_num in data:
                if total_num == 0:
                    recall = 0
                else:
                    recall = np.sum(sub_list) / total_num

                separate_result.append(recall)
            return np.mean(separate_result), separate_result

    @staticmethod
    def f1(data):
        if type(data) != list and type(data) != tuple:
            raise Exception("the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple")

        if len(data) == 0:
            return 0.0, [0.0]
        if type(data) == tuple:

            precision, _ = InformationRetrievalMetric.precision(data)
            recall, _ = InformationRetrievalMetric.recall(data)

            if precision == 0 or recall == 0:
                f1 = 0.0
            else:
                f1 = 2 * precision * recall / (precision + recall)
            return f1, [f1]

        if type(data) == list:
            separate_result = []
            for single_data in data:
                precision, _ = InformationRetrievalMetric.precision(single_data)
                recall, _ = InformationRetrievalMetric.recall(single_data)

                if precision == 0 or recall == 0:
                    f1 = 0.0
                else:
                    f1 = 2 * precision * recall / (precision + recall)

                separate_result.append(f1)
            return np.mean(separate_result), separate_result

    @staticmethod
    def mrr(data):
        if type(data) != list and type(data) != tuple:
            raise Exception("the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple")

        if len(data) == 0:
            return 0.0, [0.0]
        if type(data) == tuple:
            (sub_list, total_num) = data
            sub_list = np.array(sub_list)
            if total_num == 0:
                return 0.0, [0.0]
            else:
                ranking_array = 1.0 / (np.array(list(range(len(sub_list)))) + 1)
                mr_np = sub_list * ranking_array

                mr = 0.0
                for team in mr_np:
                    if team > 0:
                        mr = team
                        break
                return mr, [mr]

        if type(data) == list:
            separate_result = []
            for (sub_list, total_num) in data:
                sub_list = np.array(sub_list)

                if total_num == 0:
                    mr = 0.0
                else:
                    ranking_array = 1.0 / (np.array(list(range(len(sub_list)))) + 1)
                    mr_np = sub_list * ranking_array

                    mr = 0.0
                    for team in mr_np:
                        if team > 0:
                            mr = team
                            break

                separate_result.append(mr)
            return np.mean(separate_result), separate_result

    @staticmethod
    def map(data):
        if type(data) != list and type(data) != tuple:
            raise Exception("the input must be a tuple([0,...,1,...],int) or a iteration of list of tuple")

        if len(data) == 0:
            return 0.0, [0.0]
        if type(data) == tuple:
            (sub_list, total_num) = data
            sub_list = np.array(sub_list)
            if total_num == 0:
                return 0.0, [0.0]
            else:
                ranking_array = 1.0 / (np.array(list(range(len(sub_list)))) + 1)

                right_ranking_list = []
                count = 1
                for t in sub_list:
                    if t == 0:
                        right_ranking_list.append(0)
                    else:
                        right_ranking_list.append(count)
                        count += 1

                ap = np.sum(np.array(right_ranking_list) * ranking_array) / total_num
                return ap, [ap]

        if type(data) == list:
            separate_result = []
            for (sub_list, total_num) in data:
                sub_list = np.array(sub_list)

                if total_num == 0:
                    ap = 0.0
                else:
                    ranking_array = 1.0 / (np.array(list(range(len(sub_list)))) + 1)

                    right_ranking_list = []
                    count = 1
                    for t in sub_list:
                        if t == 0:
                            right_ranking_list.append(0)
                        else:
                            right_ranking_list.append(count)
                            count += 1

                    ap = np.sum(np.array(right_ranking_list) * ranking_array) / total_num

                separate_result.append(ap)
            return np.mean(separate_result), separate_result

    @staticmethod
    def fleiss_kappa(data, N, k, n):
        dataMat = np.mat(data, float)
        oneMat = np.ones((k, 1))
        sum = 0.0
        P0 = 0.0
        for i in range(N):
            temp = 0.0
            for j in range(k):
                sum += dataMat[i, j]
                temp += 1.0 * dataMat[i, j] ** 2
            temp -= n
            temp /= (n - 1) * n
            P0 += temp
        P0 = 1.0 * P0 / N
        ysum = np.sum(dataMat, axis=0)
        if sum < N * n:
            raise Exception("input data is wrong!")
        for i in range(k):
            ysum[0, i] = (ysum[0, i] / sum) ** 2
        Pe = ysum * oneMat * 1.0
        ans = float(P0 - Pe) / (1 - Pe)
        return ans[0, 0]

# main function
def main_solution(data, metric):
    """
    Compute the specified information retrieval metric for the given data.

    :param data: A list of tuples where each tuple contains a list of binary values (0 or 1) and an integer representing the total ground truth number.
    :param metric: A string specifying the metric to compute. Possible values are "precision", "recall", "f1", "mrr", "map".
    :return: A dictionary containing the computed metric value and a list of individual metric values for each tuple in the data.
    """
    if metric == "precision":
        result = InformationRetrievalMetric.precision(data)
    elif metric == "recall":
        result = InformationRetrievalMetric.recall(data)
    elif metric == "f1":
        result = InformationRetrievalMetric.f1(data)
    elif metric == "mrr":
        result = InformationRetrievalMetric.mrr(data)
    elif metric == "map":
        result = InformationRetrievalMetric.map(data)
    else:
        raise ValueError("Invalid metric specified. Choose from 'precision', 'recall', 'f1', 'mrr', 'map'.")

    return {"average_metric": result[0], "individual_metrics": result[1]}

