    elif metric == "f1":
        result = InformationRetrievalMetric.f1(data)
    elif metric == "mrr":
        result = InformationRetrievalMetric.mrr(data)
    elif metric == "map":
        result = InformationRetrievalMetric.map(data)
    else:
        raise ValueError("Invalid metric specified. Choose from 'precision', 'recall', 'f1', 'mrr', 'map'.")

    return {"average_metric": result[0], "individual_metrics": result[1]}
