from collections import defaultdict

# all class and function definitions in the code file, if any
def dfs(adj, visited, u):
    stack = [u]
    count = 0

    while stack:
        s = stack.pop()

        if not visited[s]:
            count += 1
            visited[s] = True

        for i in adj[s]:
            if not visited[i]:
                stack.append(i)

    return count

