def main_solution(number: int, shift_amount: int, shift_type: str):
    if number < 0 or shift_amount < 0:
        raise ValueError("both inputs must be positive integers")

    if shift_type == "logical_left":
        binary_number = str(bin(number))
        binary_number += "0" * shift_amount
        shifted_binary = binary_number
    elif shift_type == "logical_right":
        binary_number = str(bin(number))[2:]
        if shift_amount >= len(binary_number):
            shifted_binary = "0b0"
        else:
            shifted_binary = "0b" + binary_number[: len(binary_number) - shift_amount]
    elif shift_type == "arithmetic_right":
        if number >= 0:
            binary_number = "0" + str(bin(number)).strip("-")[2:]
        else:
            binary_number_length = len(bin(number)[3:])
            binary_number = bin(abs(number) - (1 << binary_number_length))[3:]
            binary_number = "1" + "0" * (binary_number_length - len(binary_number)) + binary_number
        if shift_amount >= len(binary_number):
            shifted_binary = "0b" + binary_number[0] * len(binary_number)
        else:
            shifted_binary = "0b" + binary_number[0] * shift_amount + binary_number[: len(binary_number) - shift_amount]
    else:
        raise ValueError("invalid shift type")

    return {"shifted_binary": shifted_binary}
