Given a raw packet data in hexadecimal format, what are the parsed details of the Ethernet frame, IPv4 packet, ICMP packet, TCP segment, and UDP segment?

The input and output requirements are as follows:

Input:
  `raw_data` (str): A hexadecimal string representing the raw packet data.

Output:
  `return` (dict): A dictionary containing the parsed packet information. The keys are the types of packets (e.g., 'Ethernet Frame', 'IPv4 Packet', 'ICMP Packet', 'TCP Segment', 'UDP Segment') and the values are dictionaries with the parsed fields.

Given the following input:

{'raw_data': '871dd2f67585b1b8fb2787d9000845000000640100000dc7c68e9109c298383a9aeb'}

Can you predict the output? Please think and then provide the exact output in the form of a JSON object enclosed in triple angle brackets, like this <<<JSON object>>> as your final answer. The keys and values of the object should strictly match the output requirement as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

# import necessary packages
import socket
import struct
import textwrap
import random

# all class and function definitions in the code file, if any
def ethernet_frame(data):
    dest_mac, src_mac, proto = struct.unpack('! 6s 6s H', data[:14])
    return get_mac_addr(dest_mac), get_mac_addr(src_mac), socket.htons(proto), data[14:]

def get_mac_addr(bytes_addr):
    bytes_str = map('{:02x}'.format, bytes_addr)
    return ':'.join(bytes_str).upper()

def ipv4_packet(data):
    version_header_length = data[0]
    version = version_header_length >> 4
    header_length = (version_header_length & 15) * 4
    ttl, proto, src, target = struct.unpack('! 8x B B 2x 4s 4s', data[:20])
    return version, header_length, ttl, proto, ipv4(src), ipv4(target), data[header_length:]

def ipv4(addr):
    return '.'.join(map(str, addr))

def icmp_packet(data):
    icmp_type, code, checksum = struct.unpack('! B B H', data[:4])
    return icmp_type, code, checksum, data[4:]

def tcp_segment(data):
    (src_port, dest_port, sequence, acknowledgment, offset_reserved_flags) = struct.unpack('! H H L L H', data[:14])
    offset = (offset_reserved_flags >> 12) * 4
    flag_urg = (offset_reserved_flags & 32) >> 5
    flag_ack = (offset_reserved_flags & 16) >> 4
    flag_psh = (offset_reserved_flags & 8) >> 3
    flag_rst = (offset_reserved_flags & 4) >> 2
    flag_syn = (offset_reserved_flags & 2) >> 1
    flag_fin = offset_reserved_flags & 1
    return src_port, dest_port, sequence, acknowledgment, flag_urg, flag_ack, flag_psh, flag_rst, flag_syn, flag_fin, data[offset:]

def udp_segment(data):
    src_port, dest_port, size = struct.unpack('! H H 2x H', data[:8])
    return src_port, dest_port, size, data[8:]

def format_multi_line(prefix, string, size=80):
    size -= len(prefix)
    if isinstance(string, bytes):
        string = ''.join(r'\x{:02x}'.format(byte) for byte in string)
        if size % 2:
            size -= 1
    return '\n'.join([prefix + line for line in textwrap.wrap(string, size)])

# main function
def main_solution(raw_data):
    # Convert JSON serializable input to original input variables
    raw_data = bytes.fromhex(raw_data)

    # Process the data
    dest_mac, src_mac, eth_proto, data = ethernet_frame(raw_data)
    result = {
        'Ethernet Frame': {
            'Destination MAC': dest_mac,
            'Source MAC': src_mac,
            'Protocol': eth_proto
        }
    }

    if eth_proto == 8:
        version, header_length, ttl, proto, src, target, data = ipv4_packet(data)
        result['IPv4 Packet'] = {
            'Version': version,
            'Header Length': header_length,
            'TTL': ttl,
            'Protocol': proto,
            'Source IP': src,
            'Target IP': target
        }

        if proto == 1:
            icmp_type, code, checksum, data = icmp_packet(data)
            result['ICMP Packet'] = {
                'Type': icmp_type,
                'Code': code,
                'Checksum': checksum
            }

        elif proto == 6:
            src_port, dest_port, sequence, acknowledgment, flag_urg, flag_ack, flag_psh, flag_rst, flag_syn, flag_fin, data = tcp_segment(data)
            result['TCP Segment'] = {
                'Source Port': src_port,
                'Destination Port': dest_port,
                'Sequence': sequence,
                'Acknowledgment': acknowledgment,
                'Flags': {
                    'URG': flag_urg,
                    'ACK': flag_ack,
                    'PSH': flag_psh,
                    'RST': flag_rst,
                    'SYN': flag_syn,
                    'FIN': flag_fin
                }
            }

        elif proto == 17:
            src_port, dest_port, length, data = udp_segment(data)
            result['UDP Segment'] = {
                'Source Port': src_port,
                'Destination Port': dest_port,
                'Length': length
            }

    # Convert the result to JSON serializable output
    return result

