# import necessary packages
from queue import LifoQueue

# all class and function definitions in the code file, if any
is_opening = {'{', '[', '('}  # set and dictionary for O(1) lookup
close_d = {'}':'{', ']':'[', ')':'('}

def delimiter_match(string):
    stk = LifoQueue()

    for c in string:
        if c in is_opening:
            stk.put(c)
        elif c in close_d:
            if stk.empty():
                return False
            s = stk.get()
            if s != close_d[c]:
                return False

    if stk.empty():
        return True
    return False

