Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

def main_solution(sequence):
    def create_state_space_tree(sequence, current_subsequence, index):
        if index == len(sequence):
            subsequences.append(current_subsequence.copy())
            return

        create_state_space_tree(sequence, current_subsequence, index + 1)
        current_subsequence.append(sequence[index])
        create_state_space_tree(sequence, current_subsequence, index + 1)
        current_subsequence.pop()

    subsequences = []
    create_state_space_tree(sequence, [], 0)
    return {"subsequences": subsequences}
