import random

# all class and function definitions in the code file, if any
def is_integer(n):
    if n in ["+inf", "-inf", "inf"]:
        return True, "+ ou - infini"

    try:
        int(n)
        return True, "correct"
    except:
        return False, "{} n'est pas un nombre correct".format(n)

