    if set == "{}":
        return True, "Ensemble vide"

    if set[0] != '{' or set[-1] != '}':
        return False, "L'ensemble {} ne commence pas par '{}' ou ne finit pas par '{}'".format(set, "{", "}")
    set = set[1:-1].split(';')
    for number in set:
        if not is_integer(number)[0]:
            return False, "{} n'est pas un nombre correct".format(number)
    return True, "correct"

