        "R1": ["G1", "G2"],
        "R2": ["G3"],
        "R3": ["G4", "G5"]
    }
    return geneAssociations, kCat

def getRosettaStone():
    # Mock data for rosettaStone
    rosettaStone = {
        "G1": "YP_001",
        "G2": "YP_002",
        "G3": "YP_003",
        "G4": "YP_004",
        "G5": "YP_005"
    }
    return rosettaStone

