        "YP_002": 20,
        "YP_003": 30,
        "YP_004": 40,
        "YP_005": 50
    }
    return proteinCounts

def getGeneCounts(rosettaStone, proteinCounts):
    geneCounts = {}
    for gene, proteinID in rosettaStone.items():
        if proteinID in proteinCounts:
            geneCounts[gene] = proteinCounts[proteinID]
    return geneCounts

def getEnzymeCounts(rosettaStone, proteinCounts, geneAssociations, geneCounts):
    enzymeCounts = {}
    for reaction, genes in geneAssociations.items():
        if isinstance(genes, list):
            count = []
            for gene in genes:
                if gene in geneCounts:
                    count.append(geneCounts[gene])
            if count:
                enzymeCounts[reaction] = sum(count)
    return enzymeCounts

def getVMax(enzymeCounts, kCat):
    vmax = {}
    avagadro = 6.02214129 * (10 ** 23)
    weight = 2.58 * (10 ** -13)
    cellsPerGram = 1 / weight
    for reaction, count in enzymeCounts.items():
        thisKCat = float(kCat[reaction])
        bound = count * (1 / avagadro) * (10 ** 3) * thisKCat * cellsPerGram * (60 ** 2)
        vmax[reaction] = bound
    return vmax

# main function
