def inverse(A):
    '''
    Inverts a sequence of turns:
    R U R' becomes R U' R'
    '''
    x = A.split(" ")
    x = [p for p in x if p != ""]
    reformatted = [l+"'" if len(l) == 1 else l if "2" in l else l[0] for l in x]
    reformatted = reformatted[::-1]
    return " ".join(reformatted)

def parse_comm(s):
    shortcut = set([",",":","[", "]"]).intersection(set(s))
    if len(shortcut) == 0:
        return(s)
    start = 0
    count = 0
    out = []
    for i in range(len(s)):
