question:
You are given a question that requires some input and output variables as follows:

Given a thesis and a related statement, how can we determine the epistemological status of the thesis based on the status of the statement and the type of relation between them? Specifically, what is the final status and additional information when the relation type is `type_of_relation` and the statement's evaluation result is `func_result`?

The input and output requirements are as follows:

Input:
- `type_of_relation` (str): The type of relation between the statement and the thesis. Possible values are 'implied', 'implying', 'equivalent', 'opposite', 'contradictory'.
- `func_result` (str): The result of the function that evaluates the statement. Possible values are 'true', 'false', 'unknown'.

Output:
- `return` (dict): A dictionary containing the final status and additional information. The keys are 'status' and 'info'. The 'status' key holds a string value ('true', 'false', 'unknown') indicating the epistemological status of the thesis. The 'info' key holds a string value providing additional information about the status.

Given the following input:

{'type_of_relation': 'implying', 'func_result': 'unknown'}

Can you predict the output? Please think and then provide the exact output in the form of a JSON object enclosed in triple angle brackets, like this <<<JSON object>>> as your final answer. The keys and values of the object should strictly match the output requirement as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

# import necessary packages
import random

# all class and function definitions in the code file, if any
class Validator():
    """A class that represents a statement related to a thesis that we want
    to prove or disprove."""

    def __init__(self, type_of_relation, func, *args, **kwargs):
        self.type = type_of_relation
        self.func = func
        self.args = args
        self.kwargs = kwargs

    def status(self):
        result = self.func(*self.args, **self.kwargs)
        if type(result) == tuple:
            status, info = result
        else:
            status = result
            info = 'no info'

        return self.process_status(status), info

    def process_status(self, status):
        if self.type == 'implied':
            if status == 'false':
                return status
            return 'unknown'

        elif self.type == 'implying':
            if status == 'true':
                return 'true'
            return 'unknown'

        elif self.type == 'equivalent':
            return status

        elif self.type == 'opposite':
            if status == 'true':
                return 'false'
            elif status == 'false':
                return 'true'
            return 'unknown'

        elif self.type == 'contradictory':
            if status == 'true':
                return 'false'
            return 'unknown'

        else:
            raise ValueError(
                f'invalid type of relation to the thesis: {self.type}')

    def __getitem__(self, key):
        if type(key) == int:
            return self.args[key]
        elif type(key) == str:
            return self.kwargs[key]
        else:
            raise TypeError(f'invalid key type: {key}')

    def __setitem__(self, key, value):
        if type(key) == int:
            self.args[key] = value
        elif type(key) == str:
            self.kwargs[key] = value
        else:
            raise TypeError(f'invalid key type: {key}')


def validate(*validators):
    """Returns the epistemological status of the thesis based on the statuses
    of the statements related to the thesis"""

    for validator in validators:
        status, info = validator.status()

        if status != 'unknown':
            return status, info

    return 'unknown', "no info"

# main function
def main_solution(type_of_relation, func_result):
    """
    Determines the epistemological status of a thesis based on the status of a related statement.

    Args:
    type_of_relation (str): The type of relation between the statement and the thesis. Possible values are 'implied', 'implying', 'equivalent', 'opposite', 'contradictory'.
    func_result (str): The result of the function that evaluates the statement. Possible values are 'true', 'false', 'unknown'.

    Returns:
    dict: A dictionary containing the final status and additional information. The keys are 'status' and 'info'.
    """
    def mock_func(*args, **kwargs):
        return func_result

    validator = Validator(type_of_relation, mock_func)
    final_status, info = validate(validator)

    return {'status': final_status, 'info': info}

