# import necessary packages
import numpy as np

# all class and function definitions in the code file, if any
def distance_diagonal_law(M):
    return np.array([np.average(np.diagonal(M, j)) for j in range(min(M.shape))])

def base_diagonal(M):
    L = distance_diagonal_law(M)
    return np.min(np.nonzero(L))

# main function
def main_solution(matrix_str):
    # Convert the input string to a numpy array
    matrix = np.array([list(map(float, row.split(','))) for row in matrix_str.split(';')])

    # Calculate the base diagonal index
    base_index = base_diagonal(matrix)

    # Return the base diagonal index as a JSON serializable output
    return int(base_index)
