def main_solution(sorted_collection, item):
    if list(sorted_collection) != sorted(sorted_collection):
        raise ValueError("sorted_collection must be sorted in ascending order")

    if sorted_collection[0] == item:
        return {"index": 0}

    bound = 1
    while bound < len(sorted_collection) and sorted_collection[bound] < item:
        bound *= 2

    left = bound // 2
    right = min(bound, len(sorted_collection) - 1)

    def binary_search(sorted_collection, item, left, right):
        if right < left:
            return -1

        midpoint = left + (right - left) // 2

        if sorted_collection[midpoint] == item:
            return midpoint
        elif sorted_collection[midpoint] > item:
            return binary_search(sorted_collection, item, left, midpoint - 1)
        else:
            return binary_search(sorted_collection, item, midpoint + 1, right)

    index = binary_search(sorted_collection, item, left, right)
    return {"index": index}

