# import necessary packages
import numpy as np

# all class and function definitions in the code file, if any
def forrester_high(X):
    ndim = X.shape[1]
    term1 = (6 * X - 2) ** 2
    term2 = np.sin(12 * X - 4)
    return np.sum(term1 * term2, axis=1) / ndim

def forrester_low(X):
    ndim = X.shape[1]
    term1 = 0.5 * forrester_high(X)
    term2 = 10 * (X - 0.5) - 5
    return term1 - (np.sum(term2, axis=1) / ndim)

# main function
def main_solution(ndim, fidelity):
    # Convert JSON serializable inputs to original input variables
    X = np.random.rand(1, ndim)

    # Invoke the appropriate function based on the fidelity
    if fidelity == 'high':
        result = forrester_high(X)
    elif fidelity == 'low':
        result = forrester_low(X)
    else:
        raise ValueError("Fidelity must be either 'high' or 'low'")

    # Convert the result to a JSON serializable output
    return float(result)
