# import necessary packages
import re
import string
import random

# all class and function definitions in the code file, if any
class DiaActItem(object):
    def __init__(self, slot, op, val):
        self.slot = slot
        self.op = op
        self.val = val
        if val is not None and isinstance(val, str) and len(val) > 0 and val[0] not in string.punctuation:
            self.val = val.lower()

    def match(self, other):
        if self.slot != other.slot:
            return True

        if self.val is None or other.val is None:
            print('None value is given in comparison between two DiaActItem')

        if self.op == '=' and other.op == '=':
            if self.val == other.val:
                return True
            if self.val == 'dontcare':
                return True
            return False

        elif self.op == '=' and other.op == '!=':
            if self.val == 'dontcare':
                return False
            elif self.val == other.val:
                return False
            else:
                return True

        elif self.op == '!=' and other.op == '=':
            if other.val == 'dontcare':
                return False
            elif self.val == other.val:
                return False
            else:
                return True

        else:
            return True

    def __eq__(self, other):
        return self.slot == other.slot and self.op == other.op and self.val == other.val

    def __hash__(self):
        return hash(repr((self.slot, self.op, self.val)))

    def __str__(self):
        return repr((self.slot, self.op, self.val))

    def __repr__(self):
        return repr((self.slot, self.op, self.val))


class DiaAct(object):
    def __init__(self, act_str):
        parsed = self._parse_act(act_str)
        self.act = parsed['act']
        self.items = parsed['slots']

    def _parse_act(self, act_str):
        result = {'act': 'null', 'slots': []}
        if act_str == "BAD ACT!!":
            return result

        m = re.search('^([^\(\)]*)\((.*)\)$', act_str.strip())
        if not m:
            return result

        result['act'] = m.group(1).strip()
        content = m.group(2)
        while len(content) > 0:
            m = re.search('^([^,!=]*)(!?=)\s*\"([^\"]*)\"\s*,?', content)
            if m:
                slot = m.group(1).strip()
                op = m.group(2).strip()
                val = m.group(3).strip("' ")
                item = DiaActItem(slot, op, val)
                content = re.sub('^([^,!=]*)(!?=)\s*\"([^\"]*)\"\s*,?', '', content)
                result['slots'].append(item)
                continue

            m = re.search('^([^,=]*)(!?=)\s*([^,]*)\s*,?', content)
            if m:
                slot = m.group(1).strip()
                op = m.group(2).strip()
                val = m.group(3).strip("' ")
                item = DiaActItem(slot, op, val)
                content = re.sub('^([^,=]*)(!?=)\s*([^,]*)\s*,?', '', content)
                result['slots'].append(item)
                continue

            m = re.search('^([^,]*),?', content)
            if m:
                slot = m.group(1).strip()
                op = None
                val = None
                item = DiaActItem(slot, op, val)
                content = re.sub('^([^,]*),?', '', content)
                result['slots'].append(item)
                continue
            raise RuntimeError('Cant parse content fragment: %s' % content)

        return result

    def to_string(self):
        s = ''
        s += self.act + '('
        for i, item in enumerate(self.items):
            if i != 0:
                s += ','
            if item.slot is not None:
                s += item.slot
            if item.val is not None:
                s = s+item.op+'"'+str(item.val)+'"'
        s += ')'
        return s

    def __eq__(self, other):
        if self.act != other.act:
            return False
        if len(self.items) != len(other.items):
            return False
        for i in self.items:
            if i not in other.items:
                return False
        for i in other.items:
            if i not in self.items:
                return False
        return True

    def __repr__(self):
        return self.to_string()

    def __str__(self):
        return self.to_string()


# main function
def main_solution(act_str):
    # Convert the input string to a DiaAct object
    dia_act = DiaAct(act_str)

    # Convert the DiaAct object to a string representation
    result = dia_act.to_string()

    # Return the string representation
    return result
