# import necessary packages
import math

# all class and function definitions in the code file, if any
def simpson(f, a, b, n):
    "Approximate the definite integral of f from a to b by Simpson's rule."

    if n % 2 != 0:
        return -1

    h  = (float(b) - a)/n

    si = 0.0
    sp = 0.0

    for i in range(1, n, 2):
        xk = a + i*h
        si += f(xk)

    for i in range(2, n, 2):
        xk = a + i*h
        sp += f(xk)

    s = 2*sp + 4*si + f(a) + f(b)

    return (h/3)*s

def g(x):
    if x < 0:
        return 0
    else:
        return math.exp(-x)

def c(t, tau):
    return g(tau) * g(t - tau)

# main function
def main_solution(t, N, n):
    # Convert JSON serializable inputs to original input variables
    t = float(t)
    N = float(N)
    n = int(n)

    def d(x):
        return c(t, x)

    # Calculate the integral using Simpson's rule
    result = simpson(d, -N, N, n)

    # Return the result as a JSON serializable output
    return result
