# import necessary packages
import random

# all class and function definitions in the code file, if any
def multiply_ints_as_polynomials(x, y):
    z = 0
    while x != 0:
        if x & 1 == 1:
            z ^= y
        y <<= 1
        x >>= 1
    return z

def number_bits(x):
    nb = 0
    while x != 0:
        nb += 1
        x >>= 1
    return nb

def mod_int_as_polynomial(x, m):
    nbm = number_bits(m)
    while True:
        nbx = number_bits(x) 
        if nbx < nbm:
            return x
        mshift = m << (nbx - nbm)
        x ^= mshift

def rijndael_multiplication(x, y):
    z = multiply_ints_as_polynomials(x, y)
    m = int('100011011', 2)
    return mod_int_as_polynomial(z, m)

def rijndael_inverse(x):
    if x == 0:
        return 0
    for y in range(1, 256):
        if rijndael_multiplication(x, y) == 1:
            return y

def dot_product(x, y):
    z = x & y
    dot = 0  
    while z != 0:
        dot ^= z & 1
        z >>= 1
    return dot 

def affine_transformation(A, x, b):
    y = 0
    for i in reversed(range(8)):
        row = (A >> 8 * i) & 0xff 
        bit = dot_product(row, x)
        y ^= (bit << i)
    return y ^ b

def rijndael_sbox(x):
    xinv = rijndael_inverse(x)
    A = int('1111100001111100001111100001111110001111110001111110001111110001', 2)
    b = int('01100011', 2)
    return affine_transformation(A, xinv, b)

# main function
def main_solution(x):
    # x is an 8-bit integer
    # return the Rijndael S-box value for the given input x
    return rijndael_sbox(x)

