You are given a question that requires some input and output variables as follows:

Given a node in a power-set lattice and the number of constraints in the system, what are the parent nodes, child nodes, descendants, or ancestors of the given node?

The input and output requirements are as follows:

Input:
  `node` (int): The integer representing the node in the power-set lattice.
  `num_constraints` (int): The number of constraints in the system.
  `operation` (str): The operation to perform, which can be one of the following: "get_parents", "get_children", "get_descendants", "get_ancestors".

Output:
  `return` (list): A list of integers representing the result of the specified operation. For example, if the operation is "get_parents", the list will contain the parent nodes of the given node.

Given the following input:

{'node': 0, 'num_constraints': 1, 'operation': 'get_descendants'}

Can you predict the output? Please think and then provide the exact output in the form of a JSON object enclosed in triple angle brackets, like this <<<JSON object>>> as your final answer. The keys and values of the object should strictly match the output requirement as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

# import necessary packages
import random

# all class and function definitions in the code file, if any
class PowersetBitLib:

    @staticmethod
    def int_to_bitlist(num: int, num_bits: int) -> list:
        return [bool((num >> i) & 1) for i in range(num_bits - 1, -1, -1)]

    @staticmethod
    def bitlist_to_int(bitlist: list) -> int:
        out = 0
        for bit in bitlist:
            out = (out << 1) | bit
        return out

    @staticmethod
    def get_parents(num: int, num_constraints: int) -> list:
        parents = []
        for i in range(num_constraints - 1, -1, -1):
            bit = (num >> i) & 1
            if bit == 1:
                parents.append(num - (1 << i))
        return parents

    @staticmethod
    def get_children(num: int, num_constraints: int) -> list:
        children = []
        for i in range(num_constraints - 1, -1, -1):
            bit = (num >> i) & 1
            if bit == 0:
                children.append(num + (1 << i))
        return children

    @staticmethod
    def is_ancestor(n1: int, n2: int) -> bool:
        return (n1 & n2) == n1

    @staticmethod
    def is_descendant(n1: int, n2: int) -> bool:
        return PowersetBitLib.is_ancestor(n2, n1)

    @staticmethod
    def one_set_bit(n: int) -> bool:
        return (n & (n - 1)) == 0

    @staticmethod
    def is_parent(n1: int, n2: int) -> bool:
        return (n2 > n1) and PowersetBitLib.one_set_bit(n2 ^ n1)

    @staticmethod
    def is_child(n1: int, n2: int) -> bool:
        return PowersetBitLib.is_parent(n2, n1)

    @staticmethod
    def get_descendants(n: int, num_cons: int) -> list:
        if num_cons == 1 and n == 0:
            return [0, 1]
        if num_cons == 1 and n == 1:
            return [1]

        descendants = []
        common = 0
        for i in range(num_cons - 1, -1, -1):
            bit = (n >> i) & 1
            if bit == 0:
                rec = PowersetBitLib.get_descendants(n & ((1 << i) - 1), i)
                descendants.extend([(common << (i + 1)) + (0 << i) + r for r in rec])
                descendants.extend([(common << (i + 1)) + (1 << i) + r for r in rec])
                break
            else:
                common = (common << 1) + 1
        return descendants if len(descendants) > 0 else [common]

    @staticmethod
    def get_ancestors(n: int, num_cons: int) -> list:
        if num_cons == 1 and n == 0:
            return [0]
        if num_cons == 1 and n == 1:
            return [0, 1]

        ancestors = []
        for i in range(num_cons - 1, -1, -1):
            bit = (n >> i) & 1
            if bit == 1:
                rec = PowersetBitLib.get_ancestors(n & ((1 << i) - 1), i)
                ancestors.extend([(0 << i) + r for r in rec])
                ancestors.extend([(1 << i) + r for r in rec])
                break
        return ancestors if len(ancestors) > 0 else [0]

    @staticmethod
    def get_num_set_bits_hamming(n: int) -> int:
        w = 0
        while n:
            w += 1
            n &= n - 1
        return w

    @staticmethod
    def get_num_set_bits(n: int) -> int:
        return bin(n)[2:].count('1')

# main function
def main_solution(node: int, num_constraints: int, operation: str) -> list:
    # Convert JSON serializable inputs to original input variables
    node = int(node)
    num_constraints = int(num_constraints)
    operation = str(operation)

    # Perform the specified operation
    if operation == "get_parents":
        result = PowersetBitLib.get_parents(node, num_constraints)
    elif operation == "get_children":
        result = PowersetBitLib.get_children(node, num_constraints)
    elif operation == "get_descendants":
        result = PowersetBitLib.get_descendants(node, num_constraints)
    elif operation == "get_ancestors":
        result = PowersetBitLib.get_ancestors(node, num_constraints)
    else:
        raise ValueError("Invalid operation specified")

    # Convert the result to a JSON serializable output
    return result

