        20: (board[1] == C and board[11] == C) or (board[18] == C and board[19] == C),
    }[location]
    return mill

def numOfPieces(board, player):
    return board.count(player)

def generateMovesMidgameEndgame(board):
    if numOfPieces(board, "W") == 3:
        return generateHopping(board)
    else:
        return generateMove(board)

def generateHopping(board):
    L = []
    for location1 in range(len(board)):
        if board[location1] == "W":
            for location2 in range(len(board)):
                if board[location2] == "x":
                    b = board[:]
                    b[location1] = "x"
                    b[location2] = "W"
                    if closeMill(location2, b):
                        generateRemove(b, L)
                    else:
                        L.append("".join(b))
    return L

def generateMove(board):
    L = []
    for location in range(len(board)):
        if board[location] == "W":
            n = neighbors(location)
            for j in n:
                if board[j] == "x":
                    b = board[:]
                    b[location] = "x"
                    b[j] = "W"
                    if closeMill(j, b):
                        generateRemove(b, L)
                    else:
                        L.append("".join(b))
    return L

def generateRemove(board, L):
    for location in range(len(board)):
        if board[location] == "B":
            if not closeMill(location, board):
                b = board[:]
                b[location] = "x"
                L.append("".join(b))

def staticEstimationMidgameEndgame(board):
    numBlackMoves = len(generateMovesMidgameEndgame(InvertBoard([i for i in board])))
    if numOfPieces(board, "B") <= 2:
        return 10000
    elif numOfPieces(board, "W") <= 2:
        return -10000
    elif numBlackMoves == 0:
        return 10000
    else:
        return 1000 * (numOfPieces(board, "W") - numOfPieces(board, "B")) - numBlackMoves

def InvertBoard(board):
    inverted_board = board[:]
    for i in range(len(inverted_board)):
        if inverted_board[i] == "W":
            inverted_board[i] = "B"
        elif inverted_board[i] == "B":
            inverted_board[i] = "W"
    return inverted_board

# main function
def main_solution(board):
    # Convert the board to a list for easier manipulation
    board_list = list(board)

    # Calculate the static estimation for the midgame endgame
    estimation = staticEstimationMidgameEndgame(board_list)

    # Return the estimation as a JSON serializable output
    return {"estimation": estimation}

