어떤 자연수 `n`이 주어졌을 때, `n`의 양의 약수 중 소수인 것들의 합은 얼마인가?

The input and output requirements are as follows:

Input:
  `n` (int): 자연수 n.

Output:
  `return` (int): n의 양의 약수 중 소수인 것들의 합.

Given the following output:

12

Can you predict a feasible input? Please reason and put your final answer in the form of a JSON object enclosed in triple angle brackets, like this <<<JSON object>>>, even if the there is only one input variable, with keys strictly matching the input variables' names as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

# import necessary packages
from functools import reduce
from math import factorial, floor, sqrt
import random

# all class and function definitions in the code file, if any
def natural_sum(n):
    """자연수 n에 대해, 1부터 n까지의 합을 구한다."""
    return n * (n+1) // 2

def prime_factorization(n):
    """절대값이 1보다 큰 정수 n에 대해, 정수 범위 안에서 소인수분해를 한다."""
    prime_factors = []
    dividend = abs(n)

    while dividend > 1:
        max_divisor = floor(sqrt(dividend))
        is_divisible = False

        for divisor in [2, *range(3, max_divisor+1, 2)]:
            if dividend % divisor == 0:
                is_divisible = True

                while dividend % divisor == 0:
                    prime_factors.append(divisor)
                    dividend //= divisor

                break

        if not is_divisible:
            prime_factors.append(dividend)
            break

    return prime_factors

def positive_divisors(n):
    """0이 아닌 정수 n에 대해, 정수 범위 안에서 양의 약수를 구한다."""
    if abs(n) == 1:
        return [1]

    prime_factors = prime_factorization(n)
    involutions = []

    while len(prime_factors) > 0:
        base = prime_factors[0]
        count = prime_factors.count(base)

        involutions.append([base ** exponent for exponent in range(count + 1)])
        prime_factors = prime_factors[count:]

    ordered_divisors = reduce(lambda a, b: [x*y for x in a for y in b], involutions, [1])
    ordered_divisors.sort()

    return ordered_divisors

def is_prime(n):
    """정수 n에 대해, 소수 판정을 한다."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    temp = n - 1
    r = 0

    while temp % 2 == 0:
        temp //= 2
        r += 1

    d = temp
    if n < 2047:
        test_bases = [2]
    elif n < 1373653:
        test_bases = [2, 3]
    else:
        raise ValueError('소수 판정 테스트 집합을 확장해야 합니다.')

    for a in test_bases:
        x = a ** d % n

        if x == 1 or x == n-1:
            continue

        composite_witness = True
        for _ in range(r-1):
            x = x ** 2 % n

            if x == n-1:
                composite_witness = False
                break

        if composite_witness:
            return False

    return True

def number_of_partitions(n, parts=None):
    """음이 아닌 정수 n에 대해, n을 분할하는 방법의 수를 구한다."""
    if parts is None:
        parts = [x for x in range(n, 0, -1)]

    def recursive_closure(n, sorted_parts):
        if n == 0:
            return 1
        elif len(sorted_parts) == 0:
            return 0
        elif len(sorted_parts) == 1:
            largest_part = sorted_parts[0]

            return (1 if n % largest_part == 0 else 0)
        else:
            result = 0
            largest_part = sorted_parts[0]
            max_available_count = n // largest_part

            for used_count in range(max_available_count, -1, -1):
                remainder = n - largest_part * used_count
                result += recursive_closure(remainder, sorted_parts[1:])

            return result

    return recursive_closure(n, parts)

# main function
def main_solution(n):
    """
    자연수 n에 대해, n의 양의 약수 중 소수인 것들의 합을 구한다.
    """
    divisors = positive_divisors(n)
    prime_divisors = [d for d in divisors if is_prime(d)]
    return sum(prime_divisors)

