# import necessary packages
from sympy import Rational

# main function
def main_solution(r):
    # Convert the input string to a Rational number
    r = Rational(r)

    # Calculate the three rational numbers a, b, c using the ryley function
    a, b, c = ryley(r)

    # Return the result as a dictionary with keys 'a', 'b', 'c'
    return {'a': str(a), 'b': str(b), 'c': str(c)}

# Function to calculate the three rational numbers a, b, c
def ryley(r):
    a = (27*r**3 + 1) / (27*r**2 - 9*r + 3)
    b = (-27*r**3 + 9*r - 1) / (27*r**2 - 9*r + 3)
    c = (-27*r**2 + 9*r) / (27*r**2 - 9*r + 3)
    return (a, b, c)
