question:
You are given a question that requires some input and output variables as follows:

Imagine you are participating in a gamified health and wellness program where you can earn points for performing various activities. You can choose to run, carry textbooks, or rest. Additionally, you can receive stars for certain activities that boost your points. However, if you receive stars too frequently, you might get bored and stop benefiting from them. Given a sequence of activities, their durations, and star offers, what will be your final hedons and health points after completing all activities and receiving stars?

The input and output requirements are as follows:

Input:
- `activities` (list of str): List of activities to perform. Each activity can be one of "running", "textbooks", or "resting".
- `durations` (list of int): List of durations for each activity in minutes. Each duration should be a positive integer.
- `star_offers` (list of str): List of activities for which stars are offered. Each activity can be one of "running", "textbooks", or "resting".

Output:
- `return` (dict): A dictionary with keys 'hedons' and 'health', representing the final hedons and health points. Both values are integers.

Given the following input:

{'activities': ['running', 'running', 'resting', 'resting', 'resting', 'textbooks', 'resting', 'running'], 'durations': [45, 25, 53, 26, 4, 21, 4, 38], 'star_offers': ['textbooks', 'resting', 'textbooks', 'running', 'running', 'running', 'textbooks', 'resting']}

Can you predict the output? Please think and then provide the exact output in the form of a JSON object enclosed in triple angle brackets, like this <<<JSON object>>> as your final answer. The keys and values of the object should strictly match the output requirement as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

# import necessary packages
import random

# all class and function definitions in the code file, if any
# they will be used in the main_solution function, you may need to modify them to meet the requirements of the main_solution function (optional)

# Global variables
cur_hedons = 0
cur_health = 0
cur_star = None
cur_star_activity = None
bored_with_stars = False
last_3_stars = [-1000, -1000, -1000]
last_activity = None
cumulative_activity_duration = 0
cur_time = 0
last_exercise_end = -1000

def initialize():
    global cur_hedons, cur_health, cur_star, cur_star_activity, bored_with_stars, last_3_stars
    global last_activity, cumulative_activity_duration, cur_time, last_exercise_end
    cur_hedons = 0
    cur_health = 0
    cur_star = None
    cur_star_activity = None
    bored_with_stars = False
    last_3_stars = [-1000, -1000, -1000]
    last_activity = None
    cumulative_activity_duration = 0
    cur_time = 0
    last_exercise_end = -1000

def is_tired():
    return last_exercise_end + 120 > cur_time

def get_effective_minutes_left_hedons(activity):
    if activity == "resting":
        return 0
    elif activity == "running":
        if not is_tired():
            result = 10
        else:
            return 0
    elif activity == "textbooks":
        if not is_tired():
            result = 20
        else:
            return 0
    else:
        return 0
    if activity == last_activity:
        result = max(result - cumulative_activity_duration, 0)
    return result

def get_effective_minutes_left_health(activity):
    if activity == "running":
        result = 180
    elif activity == "textbook":
        return 0
    else:
        return 0
    if activity == last_activity:
        result = max(result-cumulative_activity_duration, 0)
    return result

def estimate_hedons_delta(activity, duration):
    effective = get_effective_minutes_left_hedons(activity)
    star_hedons = 0
    if star_can_be_taken(activity):
        star_hedons = 3 * min(duration, 10)
    if activity == "running":
        if is_tired():
            return -2 * duration + star_hedons
        else:
            return 2 * min(effective, duration) - 2 * max(duration-effective, 0) + star_hedons
    if activity == "textbooks":
        if is_tired():
            return -2 * duration + star_hedons
        else:
            return min(effective, duration) - max(duration-effective, 0) + star_hedons
    return star_hedons

def estimate_health_delta(activity, duration):
    effective = get_effective_minutes_left_health(activity)
    if activity == "running":
        return 3 * min(effective, duration) + max(duration-effective, 0)
    if activity == "textbooks":
        return 2 * duration
    if activity == "resting":
        return 0    

def perform_activity(activity, duration):
    global bored_with_stars, cur_health, cur_hedons, cumulative_activity_duration, last_activity, cur_time, last_exercise_end
    if activity not in ["running", "textbooks", "resting"]:
        return
    if last_3_stars[2] + 180 > cur_time:
        bored_with_stars = True
    cur_hedons += estimate_hedons_delta(activity, duration)
    cur_health += estimate_health_delta(activity, duration)
    if activity != last_activity:
        cumulative_activity_duration = duration
        last_activity = activity
    cur_time += duration
    if activity in ["running", "textbooks"]:
        last_exercise_end = cur_time

def star_can_be_taken(activity):
    return cur_star_activity == activity and not bored_with_stars and cur_star == cur_time

def get_cur_hedons():
    return cur_hedons

def get_cur_health():
    return cur_health

def offer_star(activity):
    global cur_star, cur_star_activity, last_3_stars
    if activity not in ["running", "textbooks", "resting"]:
        return
    cur_star = cur_time
    cur_star_activity = activity
    last_3_stars[1:3] = last_3_stars[0:2]
    last_3_stars[0] = cur_star

def most_fun_activity_minute():
    best = "resting"
    hedons = 0
    for a in ["running", "textbooks", "resting"]:
        h = estimate_hedons_delta(a, 1)
        if h > hedons:
            best = a
            hedons = h
    return best

# main function
def main_solution(activities, durations, star_offers):
    """
    Simulates the user performing activities and receiving stars, and returns the final hedons and health points.

    Parameters:
    activities (list of str): List of activities to perform.
    durations (list of int): List of durations for each activity.
    star_offers (list of str): List of activities for which stars are offered.

    Returns:
    dict: A dictionary with keys 'hedons' and 'health', representing the final hedons and health points.
    """
    initialize()
    for i in range(len(activities)):
        perform_activity(activities[i], durations[i])
        if i < len(star_offers):
            offer_star(star_offers[i])
    return {"hedons": get_cur_hedons(), "health": get_cur_health()}

