question:
You are given a question that requires some input and output variables as follows:

In a baseball simulation, two types of agents are used to throw pitches: a simple reflex agent and a model-based agent. Each agent adjusts its pitch based on the current wind conditions. Given the type of agent and the number of pitches to simulate, what is the total number of strikes and pitches thrown by the agent after the simulation?

The input and output requirements are as follows:

Input:
- `agent_type` (str): The type of agent to simulate. Must be either "simple" for SimpleReflexAgent or "model" for ModelBasedAgent.
- `num_pitches` (int): The number of pitches to simulate. Must be a positive integer.

Output:
- `return` (dict): A dictionary containing the following keys:
  - `total_strikes` (int): The total number of strikes thrown by the agent.
  - `total_pitches` (int): The total number of pitches thrown by the agent.

Given the following output:

{'total_strikes': 43, 'total_pitches': 54}

Can you predict a feasible input? Please reason and put your final answer in the form of a JSON object enclosed in triple angle brackets, like this <<<JSON object>>>, even if the there is only one input variable, with keys strictly matching the input variables' names as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

# import necessary packages
from random import randint
from abc import abstractmethod, ABC

# all class and function definitions in the code file, if any
class Agent(ABC):
    def __init__(self):
        self.horizontalOffset = 0
        self.pitchCount = 0
        self.currentStrikes = 0
        self.currentBalls = 0
        self.outs = 0
        self.state = None
        self.strikeTotal = 0

    def updateState(self, environment):
        pass

    @abstractmethod
    def mapStateToAction(self):
        pass

    @abstractmethod
    def throwPitch(self, environment):
        pass

    def isStrike(self, pitchLocationHorizontal):
        return True if abs(pitchLocationHorizontal) < 8.5 else False

    def updateAtBat(self, pitch):
        if pitch == 'strike':
            self.currentStrikes += 1
            self.strikeTotal += 1
        else:
            self.currentBalls += 1

        if self.currentStrikes == 3 or self.currentBalls == 4:
            self.resetAtBat()

    def resetAtBat(self):
        self.outs = self.outs + 1 if self.currentStrikes == 3 else self.outs
        self.currentStrikes = 0
        self.currentBalls = 0

    def inningIsOver(self):
        return self.outs == 3

class SimpleReflexAgent(Agent):
    def updateState(self, environment):
        self.state = [environment.windSpeed, environment.windDirection]

    def mapStateToAction(self):
        def getRule(windSpeed):
            if windSpeed >= 60:
                return 'extreme'
            elif windSpeed >= 40:
                return 'high'
            elif windSpeed >= 20:
                return 'moderate'
            else:
                return 'low'

        def getAction(rule):
            return {
                'extreme': randint(10, 30),
                'high': randint(3, 27),
                'moderate': randint(0, 21),
                'low': randint(0, 12)
            }[rule]

        windSpeed = self.state[0]
        windDirection = self.state[1]
        rule = getRule(windSpeed)
        delta = getAction(rule)
        self.horizontalOffset = delta if windDirection == 'left' else (-1 * delta)

    def throwPitch(self, environment):
        self.updateState(environment)
        self.mapStateToAction()
        windEffect = (environment.windSpeed / 10) * 3
        pitchLocationHorizontal = (self.horizontalOffset + windEffect if environment.windDirection == 'right'
                                   else self.horizontalOffset - windEffect)
        pitch = "strike" if self.isStrike(pitchLocationHorizontal) else "ball"
        self.updateAtBat(pitch)
        self.pitchCount += 1

class ModelBasedAgent(Agent):
    def __init__(self):
        super().__init__()
        self.model = []

    def updateState(self, environment):
        self.state = [environment.windSpeed, environment.windDirection]

    def updateMemory(self, pitch):
        memory = [self.state[0], self.state[1], abs(self.horizontalOffset), pitch]
        self.model.append(memory)

    def mapStateToAction(self):
        def getRule(windSpeed):
            if windSpeed >= 60:
                return 'extreme'
            elif windSpeed >= 40:
                return 'high'
            elif windSpeed >= 20:
                return 'moderate'
            else:
                return 'low'

        def getAction(rule):
            return {
                'extreme': randint(6, 30),
                'high': randint(3, 27),
                'moderate': randint(0, 21),
                'low': randint(0, 12)
            }[rule]

        def checkMemory(windSpeed):
            delta = None
            for memory in self.model:
                if abs(windSpeed - memory[0]) < 10 and memory[3] == 'strike':
                    delta = memory[2]
                    break
            return delta

        windSpeed = self.state[0]
        windDirection = self.state[1]
        delta = checkMemory(windSpeed)
        if delta is None:
            rule = getRule(windSpeed)
            delta = getAction(rule)
        self.horizontalOffset = delta if windDirection == 'left' else (-1 * delta)

    def throwPitch(self, environment):
        self.updateState(environment)
        self.mapStateToAction()
        windEffect = (environment.windSpeed / 10) * 3
        pitchLocationHorizontal = (self.horizontalOffset + windEffect if environment.windDirection == 'right'
                                   else self.horizontalOffset - windEffect)
        pitch = "strike" if self.isStrike(pitchLocationHorizontal) else "ball"
        self.updateMemory(pitch)
        self.updateAtBat(pitch)
        self.pitchCount += 1

class Environment:
    def __init__(self):
        self.windSpeed = randint(0, 70)
        self.windDirection = 'right' if randint(0, 1) == 0 else 'left'

    def updateWindEffects(self):
        self.windSpeed = randint(0, 70)
        self.windDirection = 'right' if randint(0, 1) == 0 else 'left'

# main function
def main_solution(agent_type, num_pitches):
    environment = Environment()
    if agent_type == 'simple':
        agent = SimpleReflexAgent()
    elif agent_type == 'model':
        agent = ModelBasedAgent()
    else:
        raise ValueError("Invalid agent type. Choose 'simple' or 'model'.")

    for _ in range(num_pitches):
        agent.throwPitch(environment)
        environment.updateWindEffects()

    return {
        "total_strikes": agent.strikeTotal,
        "total_pitches": agent.pitchCount
    }

