# import necessary packages
from sympy import solve, sympify

# main function
def main_solution(equation: str):
    # Convert the input equation to a format that sympy can solve
    try:
        sympy_equation = sympify("Eq(" + equation.replace("=", ",") + ")")
        solutions = solve(sympy_equation)
    except Exception as e:
        return str(e)

    # Convert the solutions to a JSON serializable format
    return str(solutions)
