    i, j, nxt = start1, start2, start1 + start2
    if number in [i, j, nxt]:
        return True, [i, j, nxt]

    sequence = [i, j, nxt]
    while True:
        i, j = j, nxt
        nxt = i+j
        sequence.append(nxt)
        if nxt == number:
            return True, sequence 
        if nxt > number:
