    if matriz == []:
        return 0
    else:
        return len(matriz)

def numcolumnas(matriz):
    if matriz == []:
        return 0
    else:
        return len(matriz[0])

def crearMatriz(filas, columnas):
    matriz = crearLista(filas)
    for i in range(0, filas):
        matriz[i] = crearLista(columnas)
    return matriz

def sumaMatrices(matriz1, matriz2):
    if numfilas(matriz1) != numfilas(matriz2) or numcolumnas(matriz1) != numcolumnas(matriz2):
        return None
    filas = numfilas(matriz1)
