def main_solution(max_weight, weights, values):
    if not (isinstance(weights, (list, tuple)) and isinstance(values, (list, tuple))):
        raise ValueError("Both the weights and values vectors must be either lists or tuples")

    num_items = len(weights)
    if num_items != len(values):
        raise ValueError(f"The number of weights must be the same as the number of values. But got {num_items} weights and {len(values)} values")

    for i in range(num_items):
        if not isinstance(weights[i], int):
            raise TypeError(f"All weights must be integers but got weight of type {type(weights[i])} at index {i}")

    dp = [[0] * (max_weight + 1) for _ in range(num_items + 1)]

    for i in range(1, num_items + 1):
        for w in range(1, max_weight + 1):
            if weights[i - 1] <= w:
                dp[i][w] = max(values[i - 1] + dp[i - 1][w - weights[i - 1]], dp[i - 1][w])
            else:
                dp[i][w] = dp[i - 1][w]

    optimal_value = dp[num_items][max_weight]
    optimal_set = set()

    i, j = num_items, max_weight
    while i > 0 and j > 0:
        if dp[i - 1][j] == dp[i][j]:
            i -= 1
        else:
            optimal_set.add(i)
            j -= weights[i - 1]
            i -= 1

    return {"optimal_value": optimal_value, "optimal_set": list(optimal_set)}

