# import necessary packages
from itertools import count, islice

# all class and function definitions in the code file, if any
class Var(object):
    def __init__(self, name):
        self.name = name
    def __repr__(self):
        return self.name

def is_var(x):   return isinstance(x, Var)
def is_tuple(x): return isinstance(x, tuple)

empty_s = ()

def ext_s_no_check(var, val, s):
    assert s is () or is_tuple(s)
    return (var, val, s)

def ext_s(var, val, s):
    assert s is () or is_tuple(s)
    return None if occurs(var, val, s) else (var, val, s)

def occurs(var, val, s):
    val = walk(val, s)
    if is_var(val):
        return var is val
    elif is_tuple(val):
        return any(occurs(var, item, s) for item in val)
    else:
        return False

def walk(val, s):
    while is_var(val):
        while s is not ():
            var1, val1, s = s
            if var1 is val:
                val = val1
                break
        else:
            break
    return val

def unify(u, v, s):
    u = walk(u, s)
    v = walk(v, s)
    if u is v:
        return s
    if is_var(u):
        if is_var(v):
            return ext_s_no_check(u, v, s)
        else:
            return ext_s(u, v, s)
    elif is_var(v):
        return ext_s(v, u, s)
    elif is_tuple(u) and is_tuple(v) and len(u) == len(v):
        for x, y in zip(u, v):
            s = unify(x, y, s)
            if s is None: break
        return s
    else:
        return s if u == v else None

def reify(val, s):
    val = walk_full(val, s)
    return walk_full(val, name_vars(val))

def walk_full(val, s):
    val = walk(val, s)
    if is_var(val):
        return val
    elif is_tuple(val):
        return tuple(walk_full(item, s) for item in val)
    else:
        return val

def name_vars(val):
    k = count()
    def recur(val):
        val = walk(val, recur.s)
        if is_var(val):
            recur.s = ext_s_no_check(val, ReifiedVar(next(k)), recur.s)
        elif is_tuple(val):
            for item in val:
                recur(item)
        else:
            pass
    recur.s = empty_s
    recur(val)
    return recur.s

def ReifiedVar(k):
    return Var('_.%d' % k)

def eq(u, v):
    def goal(s):
        yield unify(u, v, s)
    return goal

def either(goal1, goal2):
    return lambda s: interleave((goal1(s), goal2(s)))

def interleave(its):
    while its:
        try:
            yield next(its[0])
        except StopIteration:
            its = its[1:]
        else:
            its = its[1:] + (its[0],)

def both(goal1, goal2):
    def goal(s):
        for opt_s1 in goal1(s):
            if opt_s1 is not None:
                for opt_s2 in goal2(opt_s1):
                    yield opt_s2
    return goal

def fresh(names_string, receiver):
    return receiver(*map(Var, names_string.split()))

def delay(thunk):
    def goal(s):
        yield None
        for opt_s in thunk()(s):
            yield opt_s
    return goal

def gen_solutions(var, goal):
    for opt_s in goal(empty_s):
        if opt_s is not None:
            yield reify(var, opt_s)

def run(var, goal, n=None):
    it = gen_solutions(var, goal)
    if n is not None:
        it = islice(it, 0, n)
    return list(it)

def appendo(x, y, z):
    return either(both(eq(x, ()), eq(y, z)),
                  fresh('xh xt', lambda xh, xt:
                            both(eq(x, (xh, xt)),
                                 fresh('zh zt', lambda zh, zt:
                                           both(eq(z, (zh, zt)),
                                                delay(lambda: appendo(xt, y, zt)))))))

# main function
def main_solution(x, y, z):
    # Convert JSON serializable inputs to original input variables
    x = tuple(x)
    y = tuple(y)
    z = tuple(z)

    # Run the appendo function to get the result
    result = run(Var('q'), appendo(x, y, z))

    # Convert the result to JSON serializable output
    return [str(item) for item in result]

