# import necessary packages
import random

# all class and function definitions in the code file, if any
def is_square(n: int) -> bool:
    n_sqrt = int(n**0.5)
    return n_sqrt * n_sqrt == n

def sum_of_two_squares2(n: int) -> bool:
    end = int(n**0.5) + 1
    return any(is_square(n - i*i) for i in range(1, end))

def sum_of_four_squares2(n: int) -> bool:
    while n % 4 == 0:
        n //= 4
    return n % 8 == 7

def num_squares(n: int) -> int:
    if is_square(n):
        return 1
    if sum_of_two_squares2(n):
        return 2
    if sum_of_four_squares2(n):
        return 4
    return 3

# main function
def main_solution(n: int) -> int:
    # all input arguments of the main_solution function should be json serializable
    # return, the returned value must be json serializable
    return num_squares(n)
