# import necessary packages
import json
from collections import Counter

# all class and function definitions in the code file, if any
def loads_sprite():
    sprite_data = {
        "spriteData": [
            {"name": "兔子"},
            {"name": "乌龟"},
            {"name": "喜鹊"},
            {"name": "郎君"},
            {"name": "孙娃"},
            {"name": "雨伞"},
            {"name": "知了"},
            {"name": "货郎"},
            {"name": "奴隶"},
            {"name": "乌鸦"}
        ]
    }
    sprite_list = sprite_data['spriteData']
    sprite_names, sprite_names_counter = [], []
    for sprite in sprite_list:
        sprite_names.append(sprite['name'])
        sprite_names_counter.append(Counter(sprite['name']))

    return sprite_names

def create_inverted_index(sprite_names):
    inverted_index = {}
    for name in sprite_names:
        for word in set(name):
            inverted_index.setdefault(word, set()).add(name)

    return inverted_index

def find_candidate_names(puzzle, inverted_index):
    candidate_names = set()
    puzzle = puzzle.replace("\t", "")
    for word in puzzle:
        candidate_names |= inverted_index.get(word, set())

    return list(candidate_names)

def solve_puzzle(puzzle, candidate_names):
    puzzle = puzzle.replace("\t", "")
    puzzle = puzzle.replace(" ", "")

    puzzle_counter = Counter(list(puzzle))
    for name in candidate_names:
        name_counter = Counter(name)
        if all(v <= puzzle_counter[k] for k, v in name_counter.items()):
            return name
    return "不存在"

# main function
def main_solution(puzzle):
    # all input arguments of the main_solution function should be json serializable (no self-defined objects, functions, np.array, set, tuple, etc.)
    sprite_names = loads_sprite()
    inverted_index = create_inverted_index(sprite_names)
    candidate_names = find_candidate_names(puzzle, inverted_index)
    result = solve_puzzle(puzzle, candidate_names)

    # return, the returned value must be json serializable (no self-defined objects, functions, np.array, set, tuple, etc.)
    return result
