# import necessary packages
import os
import re
from collections import defaultdict, Counter
from typing import Counter

# all class and function definitions in the code file, if any
# they will be used in the main_solution function, you may need to modify them to meet the requirements of the main_solution function (optional)
EDITOR_RE = re.compile(r'\[([^]]+)\]')

def LevenshteinDistance(s: str, t: str) -> int:
    # Optimisation perso, j'ai pas besoin des distances supérieures à diffMax
    if abs(len(s) - len(t)) > 2:
        return 3

    # degenerate cases
    if s == t:
        return 0
    if len(s) == 0:
        return len(t)
    if len(t) == 0:
        return len(s)

    # create two work vectors of integer distances
    v0 = list(range(len(t)+1))
    v1 = [0] * (len(t)+1)

    for i in range(len(s)):
        v1[0] = i + 1
        for j in range(len(t)):
            cost = 0 if s[i] == t[j] else 1
            v1[j + 1] = min(v1[j] + 1, v0[j + 1] + 1, v0[j] + cost)
        for j in range(len(v0)):
            v0[j] = v1[j]

    return v1[len(t)]

def testsuffix(e1: str, e2: str, suffix: str):
    return e1+suffix == e2 or e1+' '+suffix == e2 or e1 == e2+suffix or e1 == e2+' '+suffix

# main function
def main_solution(directory: str):
    variants = defaultdict(set)
    cc: Counter[str] = Counter()

    for dirpath, dirname, filenames in os.walk(directory):
        for filename in filenames:
            ma = EDITOR_RE.search(filename)
            if ma:
                ed = ma.group(1)
                cc.update([ed])
                variants[ed.casefold()].add(ed)

    result = []
    for ed, f in cc.most_common():
        variant_list = list(variants[ed.casefold()])
        result.append({"editor": ed, "count": f, "variants": variant_list})

    return result
