def main_solution(root):
    """
    Determines if a binary tree is a sum tree, where the value of every non-leaf node is equal to the sum of the values of its left and right subtrees.

    Args:
        root (dict): A dictionary representing the binary tree. Each node has 'data', 'left', and 'right' keys. 'left' and 'right' are either None or dictionaries representing the left and right subtrees.

    Returns:
        dict: A dictionary with one key:
            - is_sum_tree (bool): True if the binary tree is a sum tree, False otherwise.
    """
    def is_sum_node(node):
        if not node:
            return True
        if not node.get('left') and not node.get('right'):
            return True
        left_sum = sum_tree(node.get('left')) if node.get('left') else 0
        right_sum = sum_tree(node.get('right')) if node.get('right') else 0
        return (node['data'] == left_sum + right_sum and
                is_sum_node(node.get('left')) and
                is_sum_node(node.get('right')))

    def sum_tree(node):
        if not node:
            return 0
        return node['data'] + sum_tree(node.get('left')) + sum_tree(node.get('right'))

    return {'is_sum_tree': is_sum_node(root)}
