Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

def main_solution(max_base: int = 5) -> dict:
    from collections import defaultdict

    freqs = defaultdict(list)
    num = 0

    while True:
        digits = "".join(sorted(str(num**3)))
        freqs[digits].append(num)

        if len(freqs[digits]) == max_base:
            base = freqs[digits][0] ** 3
            return {"smallest_cube": base}

        num += 1
