# import necessary packages
from enum import Enum
from sympy.combinatorics.named_groups import SymmetricGroup, AlternatingGroup, CyclicGroup, DihedralGroup
from sympy.combinatorics.perm_groups import PermutationGroup
from sympy.combinatorics.permutations import Permutation

# all class and function definitions in the code file, if any
class S3TransitiveSubgroups(Enum):
    A3 = "A3"
    S3 = "S3"

    def get_perm_group(self):
        if self == S3TransitiveSubgroups.A3:
            return AlternatingGroup(3)
        elif self == S3TransitiveSubgroups.S3:
            return SymmetricGroup(3)

class S4TransitiveSubgroups(Enum):
    C4 = "C4"
    V = "V"
    D4 = "D4"
    A4 = "A4"
    S4 = "S4"

    def get_perm_group(self):
        if self == S4TransitiveSubgroups.C4:
            return CyclicGroup(4)
        elif self == S4TransitiveSubgroups.V:
            return four_group()
        elif self == S4TransitiveSubgroups.D4:
            return DihedralGroup(4)
        elif self == S4TransitiveSubgroups.A4:
            return AlternatingGroup(4)
        elif self == S4TransitiveSubgroups.S4:
            return SymmetricGroup(4)

def four_group():
    return PermutationGroup(
        Permutation(0, 1)(2, 3),
        Permutation(0, 2)(1, 3)
    )

# main function
def main_solution(group_name, n):
    """
    Given a group name and the symmetric group degree n, return the order of the corresponding permutation group.

    Parameters:
    group_name (str): The name of the group from the Enum classes S3TransitiveSubgroups or S4TransitiveSubgroups.
    n (int): The degree of the symmetric group (3 or 4).

    Returns:
    int: The order of the permutation group.
    """
    if n == 3:
        group_enum = S3TransitiveSubgroups[group_name]
    elif n == 4:
        group_enum = S4TransitiveSubgroups[group_name]
    else:
        raise ValueError("Invalid n value. Only n=3 or n=4 are supported.")

    perm_group = group_enum.get_perm_group()
    return perm_group.order()

