# import necessary packages
from collections import Counter

# main function
def main_solution(people):
    # Convert input to a list of integers
    people = [int(x) for x in people.split(',')]

    # Initialize the cash register
    cash_register = {25: 0, 50: 0, 100: 0}

    # Process each person in the line
    for paid in people:
        cash_register[paid] += 1
        change = paid - 25

        # Give change using available bills
        for bill in [50, 25]:
            while change >= bill and cash_register[bill] > 0:
                cash_register[bill] -= 1
                change -= bill

        # If change is not zero, return 'NO'
        if change != 0:
            return 'NO'

    # If all transactions are successful, return 'YES'
    return 'YES'
