# all class and function definitions in the code file, if any
def build_graph_from_trust(N, trust):
    graph = [[] for _ in range(N + 1)] 
    for a, b in trust:
        graph[a].append(b)
    return graph 

def find_nodes_with_no_neighbors(graph):
    candidates = []
    for i in range(1, len(graph)):
        if len(graph[i]) == 0:
            candidates.append(i)
    return candidates

def check_every_other_other_node(graph, candidate):
    for i in range(1, len(graph)):
        if i != candidate and candidate not in graph[i]:
            return False 
    return True

# main function
