You are given a question that requires some input and output variables as follows:

Given a class that enforces specific constraints on attribute values, how would you determine if a particular attribute can be set with a given value without violating any constraints? Specifically, what would be the outcome when attempting to set an attribute with a value that may be a string, a sequence of integers, a dictionary with specific keys and values, or None?

The input and output requirements are as follows:

Input:
  `attribute_name` (str): The name of the attribute to be set in the class.
  `value` (Union[str, Sequence[int], Dict[str, str], None]): The value to be assigned to the attribute. It can be a string, a sequence of integers, a dictionary with specific keys and values, or None.

Output:
  `return` (str): A string indicating the result of the operation. It will be "Success" if the value is set successfully, or an error message if the value is invalid.

Given the following input:

{'attribute_name': 'oxei', 'value': {'key1': 'value2', 'key2': 'value3'}}

Can you predict the output? Please think and then provide the exact output in the form of a JSON object enclosed in triple angle brackets, like this <<<JSON object>>> as your final answer. The keys and values of the object should strictly match the output requirement as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

# import necessary packages
from typing import Sequence, Dict, Union
import random

# all class and function definitions in the code file, if any
class Descriptor:
    def __init__(self, name=None, **opts):
        self.name = name
        self.__dict__.update(opts)

    def __set__(self, instance, value):
        instance.__dict__[self.name] = value

def Typed(expected_type, cls=None):
    if cls is None:
        return lambda cls: Typed(expected_type, cls)

    super_set = cls.__set__
    def __set__(self, instance, value):
        if not isinstance(value, expected_type):
            raise TypeError('expected ' + str(expected_type))
        super_set(self, instance, value)
    cls.__set__ = __set__
    return cls

def TypedSequence(expected_element_types, cls=None):
    if cls is None:
        return lambda cls: TypedSequence(expected_element_types, cls)

    super_set = cls.__set__
    def __set__(self, instance, value):
        if not isinstance(value, Sequence):
            raise TypeError(f'input is not Sequence type, recieved {type(value)}')
        elif not all([isinstance(el, expected_element_types) for el in value]):
            raise TypeError(f'not all elements are {expected_element_types} type(s) in {value}')
        super_set(self, instance, value)
    cls.__set__ = __set__
    return cls

def OneOf(expected_values, cls=None):
    if cls is None:
        return lambda cls: OneOf(expected_values, cls)

    super_set = cls.__set__
    def __set__(self, instance, value):
        if value not in expected_values:
            raise ValueError(f'expected one of {expected_values} recieved {value}')
        super_set(self, instance, value)
    cls.__set__ = __set__
    return cls

def MaxSized(cls):
    super_init = cls.__init__
    def __init__(self, name=None, **opts):
        if 'size' not in opts:
            raise TypeError('missing size option')
        self.size = opts['size']
        super_init(self, name, **opts)
    cls.__init__ = __init__
    super_set = cls.__set__
    def __set__(self, instance, value):
        if len(value) > self.size:
            raise ValueError('size must be < ' + str(self.size))
        super_set(self, instance, value)
    cls.__set__ = __set__
    return cls

def DictItems(expected_keys_required, expected_values, cls=None):
    if cls is None:
        return lambda cls: DictItems(expected_keys_required, expected_values, cls)

    super_set = cls.__set__
    def __set__(self, instance, value):
        if not isinstance(value, dict):
            raise TypeError(f'expected {dict}, recieved {type(value)}')
        for expected_key, required in expected_keys_required.items():
            try:
                if value[expected_key] not in expected_values[expected_key]:
                    raise ValueError(f'{value[expected_key]} invalid for key {expected_key}')
            except KeyError as e:
                if required:
                    raise e
        for recieved_key in value.keys():
            if recieved_key not in expected_keys_required:
                raise TypeError(f'Not supposed to have key {recieved_key}')
        super_set(self, instance, value)
    cls.__set__ = __set__
    return cls

@Typed(str)
class String(Descriptor):
    pass

@DictItems(expected_keys_required={}, expected_values={})
class EmptyDict(Descriptor):
    pass

@Typed((dict, type(None)))
class OptionalDict(Descriptor):
    pass

@Typed((str, type(None)))
class OptionalString(Descriptor):
    pass

@Typed(tuple)
class Tuple(Descriptor):
    pass

@MaxSized
@TypedSequence(int)
class SizedIntegerTuple(Tuple):
    pass

class checkedmeta(type):
    def __new__(cls, clsname, bases, methods):
        for key, value in methods.items():
            if isinstance(value, Descriptor):
                value.name = key
        return type.__new__(cls, clsname, bases, methods)

# main function
def main_solution(attribute_name: str, value: Union[str, Sequence[int], Dict[str, str], None]):
    class TestClass(metaclass=checkedmeta):
        if isinstance(value, str):
            attr = String(attribute_name)
        elif isinstance(value, Sequence) and all(isinstance(el, int) for el in value):
            attr = SizedIntegerTuple(attribute_name, size=len(value))
        elif isinstance(value, dict):
            attr = DictItems(expected_keys_required={"key1": True, "key2": False}, expected_values={"key1": ["value1", "value2"], "key2": ["value3", "value4"]})(EmptyDict)(attribute_name)
        elif value is None:
            attr = OptionalString(attribute_name)
        else:
            raise TypeError("Unsupported value type")

    obj = TestClass()
    try:
        setattr(obj, attribute_name, value)
        return "Success"
    except (TypeError, ValueError) as e:
        return str(e)

