# import necessary packages
import json

# all class and function definitions in the code file, if any
def word_file_to_anagram_dictionary(word_list):
    anagram_dictionary = {}
    for each_word in word_list:
        sorted_word = ''.join(sorted(each_word.strip()))
        anagram_dictionary[sorted_word] = anagram_dictionary.get(sorted_word, []) + [each_word.strip()]
    return anagram_dictionary

def find_longest_anagram_list(anagram_dictionary):
    sorted_keys = sorted(anagram_dictionary, key=lambda x: len(anagram_dictionary[x]), reverse=True)
    for each_key in sorted_keys:
        if len(anagram_dictionary[each_key]) > 1:
            return anagram_dictionary[each_key]
    return []

def find_most_possible_bingo(anagram_dictionary):
    eight_letter_anagrams = {k: v for k, v in anagram_dictionary.items() if len(k) == 8}
    if not eight_letter_anagrams:
        return "", []
    top_key = sorted(eight_letter_anagrams, key=lambda x: len(eight_letter_anagrams[x]), reverse=True)[0]
    return top_key, eight_letter_anagrams[top_key]

# main function
def main_solution(word_list):
