You are given a question that requires some input and output variables as follows:

In a fantasy role-playing game, a character has a certain amount of health and a set of spells that can be cast. Each spell is described by the number of dice rolled, the number of faces on each die, and an optional modifier that can be added or subtracted from the total roll. Given the character's health and a list of spell descriptions, what is the highest probability of successfully casting a spell that will reduce the character's health to zero or below?

The input and output requirements are as follows:

Input:
  `health` (int): The initial health of the character.
  `spell_descriptions` (list of str): A list of spell descriptions in the format "NdM[+/-K]", where N is the number of dice, M is the number of faces on each die, and K is an optional modifier.

Output:
  `return` (float): The highest probability of success among the given spell descriptions, represented as a float between 0 and 1.

Given the following output:

0

Can you predict a feasible input? Please reason and put your final answer in the form of a JSON object enclosed in triple angle brackets, like this <<<JSON object>>>, even if the there is only one input variable, with keys strictly matching the input variables' names as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

# import necessary packages
import re

# all class and function definitions in the code file, if any
def value_s_n_dice_x(s, n, x):
    import math

    def C(n, k):
        f = math.factorial
        assert n >= 0, n
        assert k >= 0, k
        return f(n) // f(k) // f(n - k)

    sum = 0
    sum_range = (s - n) // x
    for k in range(sum_range + 1):
        temp = s - x * k - 1
        assert temp >= 0, (temp, s, n, x, sum_range, k)
        sum += (-1)**k * C(n, k) * C(temp, n - 1)

    return sum

lookup = {}

for x in range(1, 21):
    for y in [4, 6, 8, 10, 12, 20]:
        total = y ** x
        for z in range(x*y, x - 1, -1):
            lookup[(z, x, y)] = value_s_n_dice_x(z, x, y) / total + lookup.get((z + 1, x, y), 0)

def get_probability(target, x, y):
    if target > x * y:
        return 0

    if target <= x:
        return 1

    return lookup[(target, x, y)]

def get_chance(h, s):
    pattern = re.compile(r"(\d+)d(\d+)(([+-])(\d+))?")
    match = pattern.match(s)
    if match:
        x, y, op, z = match.group(1, 2, 4, 5)
    else:
        raise Exception("Wrong regex")

    target = h
    if op == '+':
        target -= int(z)
    elif op == '-':
        target += int(z)

    return get_probability(target, int(x), int(y))

def solve(h, spells):
    return max(get_chance(h, s) for s in spells)

# main function
def main_solution(health, spell_descriptions):
    # all input arguments of the main_solution function should be json serializable (no self-defined objects, functions, np.array, set, tuple, etc.)
    # return, the returned value must be json serializable (no self-defined objects, functions, np.array, set, tuple, etc.)
    return solve(health, spell_descriptions)

