# import necessary packages
import numpy as np

# main function
def main_solution(x_values):
    # Convert the input list to a numpy array
    x = np.array(x_values)

    # Calculate the analytical derivative of the function x^2 * sin(x)
    derivative = 2 * x * np.sin(x) + (x**2) * np.cos(x)

    # Convert the result to a list and return
    return derivative.tolist()
