# import necessary packages
import random

# all class and function definitions in the code file, if any
def twos_comp(x):
    return (~x) + 1

numberspace = 2**32  # seq numbers are up to but not including this
halfspace = numberspace / 2

def wrap(x):
    '''
    emulates the cast to int used in the C tcp seq # subtraction algo:
    (int)( (a) - (b) ). Basically, if a number's absolute value is greater
    than half the (unsigned) number space, it needs to be wrapped.
    '''
    # if abs(x) > numberspace / 2, its value must be reduced by numberspace/2,
    # and its sign must be flipped
    if x > halfspace:
        x = 0 - (x - halfspace)
    elif x < -halfspace:
        x = 0 - (x + halfspace)
    # x is now normalized
    return x

def subtract(a, b):
    '''Calculate the difference between a and b, two python longs,
    in a manner suitable for comparing two TCP sequence numbers in a
    wrap-around-sensitive way.'''
    return wrap(a - b)

def lt(a, b):
    return subtract(a, b) < 0

def gt(a, b):
    return subtract(a, b) > 0

def lte(a, b):
    return subtract(a, b) <= 0

def gte(a, b):
    return subtract(a, b) >= 0

# main function
def main_solution(seq_num1, seq_num2, comparison_type):
    # all input arguments of the main_solution function should be json serializable (no self-defined objects, functions, np.array, set, tuple, etc.)
    # if you need to invoke functions that require non-json serializable inputs, like those defined in the reference code file, you need to convert them (optional)
    if comparison_type == "lt":
        result = lt(seq_num1, seq_num2)
    elif comparison_type == "gt":
        result = gt(seq_num1, seq_num2)
    elif comparison_type == "lte":
        result = lte(seq_num1, seq_num2)
    elif comparison_type == "gte":
        result = gte(seq_num1, seq_num2)
    else:
        raise ValueError("Invalid comparison type")

    # return, the returned value must be json serializable (no self-defined objects, functions, np.array, set, tuple, etc.)
    return {"result": result}
