def main_solution(num: int) -> dict:
    import math
    octal = 0
    counter = 0
    while num > 0:
        remainder = num % 8
        octal = octal + (remainder * math.floor(math.pow(10, counter)))
        counter += 1
        num = math.floor(num / 8)
    return {"octal": f"0o{int(octal)}"}
