# import necessary packages
import csv
from datetime import date, datetime, timedelta, time
from collections import defaultdict

# Constants
CONST_START_OF_DAY = time(8, 0, 0)
CONST_END_OF_DAY = time(22, 0, 0)

# Helper functions
def adjustTime(startTime, endTime):
    return [max(startTime, CONST_START_OF_DAY), min(endTime, CONST_END_OF_DAY)]

def stringToDate(dateString):
    return date(*map(int, dateString.split("-")))

def stringToTime(timeString):
    return time(*map(int, timeString.split(":")))

def dayInRange(dayDate, currDate):
    return currDate <= dayDate and currDate + timedelta(days=7) >= dayDate

def timeInRange(dayTime):
    return dayTime >= CONST_START_OF_DAY and dayTime <= CONST_END_OF_DAY

def timeToDateTime(date, time):
    return datetime.combine(date, time)

def applyEvent(freeTime, key, times):
    currentFreeTime = freeTime[key]
    startTime, endTime = times
    newFreeTime = []
    for block in currentFreeTime:
        if startTime <= block[0] and endTime >= block[1]:
            continue
        elif startTime < block[0] and endTime < block[0]:
            newFreeTime.append(block)
        elif startTime > block[1] and endTime > block[1]:
            newFreeTime.append(block)
        elif startTime > block[0] and endTime < block[1]:
            newFreeTime.append([block[0], (timeToDateTime(key, startTime) - timedelta(seconds=1)).time()])
            newFreeTime.append([(timeToDateTime(key, endTime) + timedelta(seconds=1)).time(), block[1]])
        elif startTime <= block[0]:
            newFreeTime.append([(timeToDateTime(key, endTime) + timedelta(seconds=1)).time(), block[1]])
        elif endTime >= block[1]:
            newFreeTime.append([block[0], (timeToDateTime(key, startTime) - timedelta(seconds=1)).time()])
    freeTime[key] = newFreeTime

def updateFreeTime(freeTime, row, currDate):
    startString = row[1].strip().split()
    endString = row[2].strip().split()
    startDay, endDay = list(map(stringToDate, [startString[0], endString[0]]))
    startTime, endTime = list(map(stringToTime, [startString[1], endString[1]]))
    if startDay == endDay:
        if dayInRange(startDay, currDate) and (timeInRange(startTime) or timeInRange(endTime)):
            applyEvent(freeTime, startDay, adjustTime(startTime, endTime))
    else:
        if startTime <= CONST_END_OF_DAY and dayInRange(startDay, currDate):
            applyEvent(freeTime, startDay, adjustTime(startTime, CONST_END_OF_DAY))
        if endTime >= CONST_START_OF_DAY and dayInRange(endDay, currDate):
            applyEvent(freeTime, endDay, adjustTime(CONST_START_OF_DAY, endTime))
        for i in range(1, (endDay - startDay).days):
            middleDay = (startDay + timedelta(days=i))
            if dayInRange(middleDay, currDate):
                applyEvent(freeTime, middleDay, [CONST_START_OF_DAY, CONST_END_OF_DAY])

def findLargestFreeTime(freeTime, currDate):
    largestDuration = timedelta(0)
    output = [currDate, CONST_START_OF_DAY, CONST_START_OF_DAY]
    for i in range(7):
        key = currDate + timedelta(days=i)
        for block in freeTime[key]:
            duration = timeToDateTime(key, block[1]) - timeToDateTime(key, block[0])
            if duration > largestDuration:
                largestDuration = duration
                output = [key, block[0], block[1]]
    return output

# main function
def main_solution(events_csv):
    currDate = datetime.now().date()
    freeTime = defaultdict(list)

    for i in range(7):
        freeTime[currDate + timedelta(days=i)].append([CONST_START_OF_DAY, CONST_END_OF_DAY])

    reader = csv.reader(events_csv.split('\n'), delimiter=",")
    for row in reader:
        if row:  # Ensure the row is not empty
            updateFreeTime(freeTime, row, currDate)

    result = findLargestFreeTime(freeTime, currDate)
    return {"day": result[0].strftime("%Y-%m-%d"), "startTime": result[1].strftime("%H:%M:%S"), "endTime": result[2].strftime("%H:%M:%S")}

