# import necessary packages
import random

# all class and function definitions in the code file, if any
class SH_automata_firms:
    def __init__(self, I, R, initial_state="s_0", final_state="s_f"):
        self.I = I
        self.R = R
        self.initial_state = initial_state
        self.final_state = final_state
        self.states = set()
        for state in [initial_state, final_state] + list(map(lambda x: f"s_{x}", R)):
            self.add_state(state)
        self.build_transitions()

    def build_transitions(self):
        self.transitions = {state: dict() for state in self.states}
        for word in self.I:
            current_state = self.initial_state 
            firm = ""
            for symbol in word:
                if symbol not in self.R:
                    firm += symbol
                else:
                    next_state = f"s_{symbol}"
                    self.add_transition(current_state, next_state, firm)
                    current_state = next_state
                    firm = ""
            if firm != "":
                self.add_transition(current_state, self.final_state, firm)

    def add_state(self, state_name):
        if state_name not in self.states:
            self.states.add(state_name)

    def add_transition(self, src, dst, word):
        if src in self.states and dst in self.states:
            self.transitions[src][word] = list(set(self.transitions[src].get(word, []) + [dst]))

    def get_max_firm_subwords(self, I, R):
        max_firms = []
        for word in I:
            firm = ""
            for symbol in word:
                if symbol not in R:
                    firm += symbol
                else:
                    max_firms.append(firm)
                    firm = ""
            max_firms.append(firm)
        return max_firms

    def check_word(self, word):
        max_firms = self.get_max_firm_subwords([word], self.R)
        states_stack = [(self.initial_state, 0)]
        while True:
            try:
                current_state, firm_idx = states_stack.pop()
                if current_state == self.final_state and firm_idx == len(max_firms): 
                    return True
                elif firm_idx == len(max_firms):
                    continue
                else:
                    next_states = self.transitions[current_state].get(max_firms[firm_idx], [])
                    if len(next_states) > 0:
                        for state in next_states:
                            states_stack.append((state, firm_idx+1))
            except:
                break
        return False

# main function
def main_solution(I, R, word):
    """
    This function checks if a given word belongs to the language of an SH-automata defined by initial words and splicing rules.

    Parameters:
    I (list of str): List of initial words of the splicing system.
    R (list of str): List of splicing rules.
    word (str): The word to check if it belongs to the language of the SH-automata.

    Returns:
    bool: True if the word belongs to the language, False otherwise.
    """
    automata = SH_automata_firms(I, R)
    return automata.check_word(word)

