def main_solution(infix_equation: str) -> dict:
    """
    Converts an infix equation to its prefix notation.

    Args:
        infix_equation (str): The infix equation to be converted.

    Returns:
        dict: A dictionary containing the prefix notation of the equation.
    """
    def infix_2_postfix(infix: str) -> str:
        stack = []
        post_fix = []
        priority = {
            "^": 3,
            "*": 2,
            "/": 2,
            "%": 2,
            "+": 1,
            "-": 1,
        }

        for x in infix:
            if x.isalpha() or x.isdigit():
                post_fix.append(x)
            elif x == "(":
                stack.append(x)
            elif x == ")":
                if len(stack) == 0:
                    raise IndexError("list index out of range")
                while stack[-1] != "(":
                    post_fix.append(stack.pop())
                stack.pop()
            elif len(stack) == 0:
                stack.append(x)
            else:
                while stack and stack[-1] != "(" and priority[x] <= priority[stack[-1]]:
                    post_fix.append(stack.pop())
                stack.append(x)

        while len(stack) > 0:
            if stack[-1] == "(":
                raise ValueError("invalid expression")
            post_fix.append(stack.pop())

        return "".join(post_fix)

    def infix_2_prefix(infix: str) -> str:
        reversed_infix = list(infix[::-1])
        for i in range(len(reversed_infix)):
            if reversed_infix[i] == "(":
                reversed_infix[i] = ")"
            elif reversed_infix[i] == ")":
                reversed_infix[i] = "("
        return (infix_2_postfix("".join(reversed_infix)))[::-1]

    infix_equation = "".join(infix_equation.split())
    prefix_notation = infix_2_prefix(infix_equation)
    return {"prefix_notation": prefix_notation}

