# import necessary packages
import random

# all class and function definitions in the code file, if any
class Node:
    def __init__(self, child_nodes, metadata_entries):
        self.child_nodes = child_nodes
        self.metadata_entries = metadata_entries

def parse_digits(digit_list):
    num_children = digit_list.pop(0)
    num_metadata = digit_list.pop(0)
    child_nodes = [parse_digits(digit_list) for _ in range(num_children)]
    metadata_entries = [digit_list.pop(0) for _ in range(num_metadata)]
    return Node(child_nodes, metadata_entries)

def sum_metadata_entries(node):
    if not node:
        return 0

    child_sums = map(sum_metadata_entries, node.child_nodes)

    return sum([*child_sums, *node.metadata_entries])

# main function
def main_solution(digit_list):
    # Convert the JSON serializable input to the original input variables
    digit_list = list(map(int, digit_list.split()))

    # Parse the digit list to create the root node
    root_node = parse_digits(digit_list)

    # Calculate the sum of all metadata entries
    result = sum_metadata_entries(root_node)

    # Return the result as a JSON serializable output
    return result
