# Helper functions from the original code file
def calc_soma(n_sem_dig):
    soma = 0 
    i = len(n_sem_dig) - 1
    cont = 1
    while i >= 0:
        if cont % 2 != 0:
            digito = int(n_sem_dig[i]) * 2
            if digito > 9:
                digito = digito - 9
        else:
            digito = int(n_sem_dig[i])
        cont += 1
        i -= 1
        soma += digito
    return soma

def luhn_verifica(n_string):
    n_sem_dig = str(int(n_string) // 10)
    ult_dig = int(n_string) % 10
    soma_final = calc_soma(n_sem_dig) + ult_dig
    return soma_final % 10 == 0

def comeca_por(cad1, cad2):
    l1 = len(cad1)
    l2 = len(cad2)
    cad3 = str(int(cad1) // 10**(l1 - l2))
    return cad3 == cad2

def comeca_por_um(cad, t_cads):
    for i in t_cads:
        if comeca_por(cad, i):
            return True
    return False

def valida_iin(n_string):
    if comeca_por_um(n_string, ('34', '37')) and len(n_string) == 15:
        return 'American Express'
    elif comeca_por_um(n_string, ('309', '36', '38', '39')) and len(n_string) == 14:
        return 'Diners Club International'
    elif comeca_por_um(n_string, ('65',)) and len(n_string) == 16:
