def bridge(mask):
    tmp = mask
    if mask == 0b111111:
        groups = 1
    elif mask == 0:
        groups = 0
    else:
        # rotate so left-most bit is 1 and right-most bit is 0:
        while (mask & 1) or not (mask & 0b100000):
            mask = (mask >> 1) | ((mask & 1) << 5)
        groups = 0
        while mask:
            while not mask & 1:
                mask >>= 1
            while mask & 1:
                mask >>= 1
            groups += 1
    return groups > 1

