# import necessary packages
import random

# all class and function definitions in the code file, if any
class Bit:
    @staticmethod
    def len(data):
        return len(data) * 8

    @staticmethod
    def get(data, iterator):
        byte = int(iterator / 8)
        offset = 7 - (iterator % 8)
        mask = 1 << offset
        return 1 if data[byte] & mask else 0

    @staticmethod
    def set(data, iterator, value):
        byte = int(iterator / 8)
        offset = 7 - (iterator % 8)
        if value:
            mask = 1 << offset
            data[byte] = data[byte] | mask
        else:
            mask = ~(1 << offset)
            data[byte] = data[byte] & mask

    @staticmethod
    def equal(data1, start1, data2, start2, lengthToCompare):
        for i in range(lengthToCompare):
            if Bit.get(data1, start1 + i) != Bit.get(data2, start2 + i):
                return False
        return True

class BitOver:
    def __init__(self, data):
        self._data = data

    def len(self):
        return Bit.len(self._data)

    def get(self, iterator):
        return Bit.get(self._data, iterator)

    def set(self, iterator, value):
        Bit.set(self._data, iterator, value)

    def getAsInt(self, key):
        bitsList = self.__getitem__(key)
        power = len(bitsList) - 1
        output = 0
        for bit in bitsList:
            if bit:
                output += 2 ** power
            power -= 1
        return output

    def writeInt(self, iterator, value, dimension):
        for power in range(dimension):
            v = 2 ** (power + 1)
            if value % v:
                self.set(iterator + dimension - power - 1, 1)
                value -= 2 ** power
            else:
                self.set(iterator + dimension - power - 1, 0)

    def __getitem__(self, key):
        if isinstance(key, slice):
            return [self[ii] for ii in range(*key.indices(len(self)))]
        elif isinstance(key, int):
            if key < 0:
                key += len(self)
            if key >= len(self):
                raise IndexError("The index (%d) is out of range." % key)
            return Bit.get(self._data, key)
        else:
            raise TypeError("Invalid argument type.")

    def __setitem__(self, key, value):
        if isinstance(key, slice):
            self.writeInt(key.start, value, key.stop - key.start)
        elif isinstance(key, int):
            if key < 0:
                key += len(self)
            if key >= len(self):
                raise IndexError("The index (%d) is out of range." % key)
            return Bit.set(self._data, key, value)
        else:
            raise TypeError("Invalid argument type.")

# main function
def main_solution(data1, data2, start1, start2, lengthToCompare):
    # Convert JSON serializable inputs to original input variables
    data1 = bytearray(data1)
    data2 = bytearray(data2)

    # Core logic
    result = Bit.equal(data1, start1, data2, start2, lengthToCompare)

    # Convert output to JSON serializable
    return result

