# import necessary packages
from collections import defaultdict

# main function
def main_solution(s1, s2, nrelated):
    # Convert inputs to ensure they are JSON serializable
    s1 = str(s1)
    s2 = str(s2)
    nrelated = int(nrelated)

    if s1 is None or s2 is None:
        raise Exception("you must provide two strings")

    if len(s1) != len(s2):
        return False

    s1_letters = defaultdict(int)
    s2_letters = defaultdict(int)

    for c in s1:
        s1_letters[c] += 1

    for c in s2:
        s2_letters[c] += 1

    if s1_letters != s2_letters:
        return False

    d = {}
    swaps = 0
    for i in range(len(s1)):
        if s1[i] != s2[i] and not (s2[i], s1[i]) in d:
            d[(s1[i], s2[i])] = True
        elif s1[i] != s2[i] and (s2[i], s1[i]) in d:
            swaps += 1
            d.pop((s2[i], s1[i]))

    return swaps == nrelated
