# import necessary packages
import math

# all class and function definitions in the code file, if any
def f(lamb):
    return lamb * math.cosh(50.0 / lamb) - lamb - 23.0

def Df(lamb):
    return math.cosh(50.0 / lamb) - (50.0 / lamb) * math.sinh(50.0 / lamb) - 1.0

def Dist(lamb):
    return 2.0 * lamb * math.sinh(50.0 / lamb)

# main function
def main_solution(initial_lambda, iterations):
    lamb = initial_lambda
    for n in range(1, iterations + 1):
        lamb = lamb - (f(lamb)) / (Df(lamb))

    d = Dist(lamb)
    return {"lambda": lamb, "cable_length": d}
