# import necessary packages
import fractions

# all class and function definitions in the code file, if any
def frac(x1, n1):
    if n1 == 0: return fractions.Fraction(f"0.{x1}")
    n = len(x1)
    tendiv = n - n1
    repeating = x1[n-n1:] if x1[n-n1:] else "0"
    nonrepeating = x1[:n-n1] if x1[:n-n1] else "0"
    return raToFrac(nonrepeating) + irraToFrac(repeating) * fractions.Fraction(1, 10**tendiv)

def raToFrac(nonrepeating):
    return fractions.Fraction(int(nonrepeating), 10**(len(nonrepeating)))

def irraToFrac(repeating):
    return fractions.Fraction(int(repeating), (10**len(repeating)) - 1)

# main function
def main_solution(x1, n1, x2, n2):
    # all input arguments of the main_solution function should be json serializable (no self-defined objects, functions, np.array, set, tuple, etc.)
    a = frac(x1, n1)
    b = frac(x2, n2)
    c = a + b
    # return, the returned value must be json serializable (no self-defined objects, functions, np.array, set, tuple, etc.)
    return f"{c.numerator}/{c.denominator}"
