def num_of_repeats(bytestring, blocklength=16):
    blocks = [bytestring[i:i+blocklength] for i in range(0, len(bytestring), blocklength)]
    repeat_counter = collections.Counter(blocks)
    repeats = 0
    for block in repeat_counter.keys():
