    repeats = num_of_repeats(bytestring, blocklength)

    # Find the position of the first repeating block
    first_repeat_pos = first_block_which_repeats_pos(bytestring, blocklength)

    # Return the results as a dictionary
    return {
        "num_of_repeats": repeats,
        "first_repeat_pos": first_repeat_pos
