Output:
  `return` (dict): A dictionary containing the following keys:
    - `'bounding_rectangle'` (str): A string representation of the bounding rectangle.
    - `'capacity'` (int): The capacity of the quadtree.
    - `'points'` (list of str): A list of string representations of the points inserted into the quadtree.
    - `'northwest'` (str or None): A string representation of the northwest quadrant if it exists, otherwise `None`.
    - `'northeast'` (str or None): A string representation of the northeast quadrant if it exists, otherwise `None`.
    - `'southwest'` (str or None): A string representation of the southwest quadrant if it exists, otherwise `None`.
    - `'southeast'` (str or None): A string representation of the southeast quadrant if it exists, otherwise `None`.

Given the following input:

{'width': 31, 'height': 55, 'capacity': 3, 'points': [{'x': 5, 'y': 8}]}

Can you predict the output without writing any code? Please think and then provide the exact output in the form of a JSON object as your final answer. The keys and values of the object should strictly match the output requirement as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

# import necessary packages
import random

# all class and function definitions in the code file, if any
class Point(object):
    def __init__(self, x, y):
        self.x, self.y = x, y

    def __repr__(self):
        return 'Point(x={}, y={})'.format(self.x, self.y)

    def __add__(self, other):
        if isinstance(other, Point):
            return Point(self.x + other.x, self.y + other.y)


class Rect(object):
    def __init__(self, point, width, height):
        self.origin = point
        self.set(point.x, point.y, width, height)
        self.width, self.height = width, height

    def set(self, x=None, y=None, w=None, h=None):
        self._x = self._x if x is None else x
        self._y = self._y if y is None else y
        self._w = self._w if w is None else w
        self._h = self._h if h is None else h
        self._quad = ('v2f', (self._x, self._y,
                              self._x + self._w, self._y,
                              self._x + self._w, self._y + self._h,
                              self._x, self._y + self._h))

    def __repr__(self):
        return 'Rect(p={}, w={}, h={})'.format(self.origin, self.width, self.height)

    def __contains__(self, other):
        if isinstance(other, Point):
            return (
                other.x >= self.origin.x and other.x <= self.origin.x + self.width and
                other.y >= self.origin.y and other.y <= self.origin.y + self.height
            )


class Quadtree(object):
    def __init__(self, bounding_rectangle, capacity):
        self.bounding_rectangle = bounding_rectangle
        self.capacity = capacity
        self.points = []
        self.northwest = None
        self.northeast = None
        self.southwest = None
        self.southeast = None

    def subdivide(self):
        width = self.bounding_rectangle.width
        height = self.bounding_rectangle.height
        origin = self.bounding_rectangle.origin
        self.northwest = Quadtree(Rect(origin + Point(width/2, height/2), width/2, height/2), self.capacity)
        self.northeast = Quadtree(Rect(origin + Point(0, height/2), width/2, height/2), self.capacity)
        self.southwest = Quadtree(Rect(origin, width/2, height/2), self.capacity)
        self.southeast = Quadtree(Rect(origin + Point(width/2, 0), width/2, height/2), self.capacity)

    def insert(self, point):
        if point not in self.bounding_rectangle:
            return False

        if len(self.points) < self.capacity:
            self.points.append(point)
            return True

        if self.northwest is None:
            self.subdivide()

        if self.northwest.insert(point):
            return True

        if self.northeast.insert(point):
            return True

        if self.southwest.insert(point):
            return True

        if self.southeast.insert(point):
            return True

        return False

# main function
def main_solution(width, height, capacity, points):
    # Convert JSON serializable inputs to original input variables
    bounding_rectangle = Rect(Point(0, 0), width, height)
    quadtree = Quadtree(bounding_rectangle, capacity)

    # Insert points into the quadtree
    for point in points:
        quadtree.insert(Point(point['x'], point['y']))

    # Convert the result to JSON serializable output
    result = {
        'bounding_rectangle': repr(quadtree.bounding_rectangle),
        'capacity': quadtree.capacity,
        'points': [repr(p) for p in quadtree.points],
        'northwest': repr(quadtree.northwest) if quadtree.northwest else None,
        'northeast': repr(quadtree.northeast) if quadtree.northeast else None,
        'southwest': repr(quadtree.southwest) if quadtree.southwest else None,
        'southeast': repr(quadtree.southeast) if quadtree.southeast else None
    }

    return result
