# import necessary packages
from collections import namedtuple

# main function
def main_solution(destination, horses):
    """
    Calculate the maximum constant speed Annie can choose for her horse to reach the destination without passing any other horses.

    Parameters:
    destination (int): The kilometer at which Annie's destination is located.
    horses (list of dict): A list of dictionaries where each dictionary represents a horse with keys 'kilometer' and 'speed'.

    Returns:
    float: The maximum constant speed Annie can choose for her horse.
