            for attr_name, attr_value in attr_dict.items():
                new_H._hyperedge_attributes[hyperedge_id][attr_name] = copy.copy(attr_value)
        new_H._star = self._star.copy()
        for node in self._node_attributes.keys():
            new_H._star[node] = self._star[node].copy()
        for frozen_nodes, hyperedge_id in self._node_set_to_hyperedge.items():
            new_H._node_set_to_hyperedge[frozen_nodes] = copy.copy(hyperedge_id)
        new_H._current_hyperedge_id = self._current_hyperedge_id
        return new_H

# main function
def main_solution(nodes, hyperedges):
    """
    Constructs an undirected hypergraph from the given nodes and hyperedges, and returns the IDs of the hyperedges.

    :param nodes: List of nodes to be added to the hypergraph.
    :param hyperedges: List of lists, where each inner list represents a set of nodes forming a hyperedge.
    :return: List of strings representing the IDs of the hyperedges added to the hypergraph.
    """
    hypergraph = UndirectedHypergraph()
    hypergraph.add_nodes(nodes)
    hyperedge_ids = hypergraph.add_hyperedges(hyperedges)
    return hyperedge_ids

