# import necessary packages
import json

# all class and function definitions in the code file, if any
class Song:
    def __init__(self, name):
        self.name = name
        self.next = None

    def next_song(self, song):
        self.next = song

    def is_repeating_playlist(self):
        """
        :returns: (bool) True if the playlist is repeating, False if not.
        """
        song = self
        playlist = [song]
        while isinstance(song.next, Song):
            if song.next in playlist:
                return True
            else:
                playlist.append(song.next)
                song = song.next

        return False

# main function
def main_solution(playlist_json):
    # Convert JSON input to a list of Song objects
    playlist_data = json.loads(playlist_json)
    songs = {name: Song(name) for name in playlist_data.keys()}

    for name, next_name in playlist_data.items():
        if next_name:
            songs[name].next_song(songs[next_name])

    # Check if the playlist is repeating
    is_repeating = songs[list(playlist_data.keys())[0]].is_repeating_playlist()

    # Return the result as a JSON serializable output
    return is_repeating
