You are given a question that requires some input and output variables as follows:

Given a list of course prerequisites, determine if there is a cycle in the course dependency graph. If no cycle exists, provide the topological order of the courses. What is the result of the analysis for the given prerequisites?

The input and output requirements are as follows:

Input:
  `prereq` (list of lists): A list of prerequisite pairs where each pair `[a, b]` indicates that course `a` must be taken before course `b`.

Output:
  `return` (dict): A dictionary with two keys:
    - `is_cycle` (bool): Indicates whether a cycle exists in the graph.
    - `topological_order` (list): A list of course IDs in topological order if no cycle exists, otherwise an empty list.

Given the following input:

{'prereq': [[2, 0], [2, 1], [1, 2], [2, 0], [1, 2], [0, 1], [1, 0], [2, 0], [1, 0], [0, 2], [1, 2], [1, 0], [1, 2]]}

Can you predict the output? Please think and then provide the exact output in the form of a JSON object enclosed in triple angle brackets, like this <<<JSON object>>> as your final answer. The keys and values of the object should strictly match the output requirement as specified.

Tip: Here is a reference code snippet for this question. You can refer to this code to guide your reasoning but not copy spans of code directly.

# import necessary packages
import random

# all class and function definitions in the code file, if any
class Node:
    WHITE = 0
    BLACK = 1
    GREY = 2

    def __init__(self, data):
        self.data = data
        self.neighbors = []
        self.color = self.WHITE
        self.level = 0


class Graph:
    t = 0
    def __init__(self):
        self.__node_list = {}

    def populate_graph(self, adjacency_matrix):
        '''
        It helps in creating a graph given it's adjacency matrix.
        '''
        for v in adjacency_matrix:
            n = Node(v)
            self.__node_list[v] = n
        for v, val in adjacency_matrix.items():
            n = self.__lookup_node(v)
            temp = []
            for name in val:
                nod = self.__lookup_node(name)
                temp.append(nod)
            n.neighbors = temp

    def  __lookup_node(self, data):
        return self.__node_list[data] 

    def dfs_forest(self):
        path = []
        timestamp = {}
        is_cycle =  False
        for n in self.__node_list.values():
            n.color = Node.WHITE
        for n in self.__node_list.values():
            if n.color == Node.WHITE:
                  iscycle, path, timestamp =  self.__dfs_call(n, path, timestamp) 
                  is_cycle = iscycle or is_cycle
        return is_cycle, path, timestamp

    def __dfs_call(self, n, path, timestamp):
        flag = False
        n.color = Node.GREY
        path.append(n.data)
        for nod in n.neighbors:
            if nod.color == Node.GREY:
                flag = True
            elif nod.color == Node.WHITE:
                flag1, path, timestamp = self.__dfs_call(nod, path, timestamp)
                flag = flag1 or flag
        n.color = n.BLACK
        self.t = self.t + 1
        timestamp[n] = self.t
        return flag, path, timestamp

def make_adjacency(n, prereq):
    vertex = set()
    adjacency = {}
    for val in prereq:
        if val[0] not in vertex:
            vertex.add(val[0])
        if val[1] not in vertex:
            vertex.add(val[1])
        adjacency.setdefault(val[0], []).append(val[1])

    for v in vertex:
        if v not in adjacency:
            adjacency[v] = []
    return  adjacency, vertex

# main function
def main_solution(prereq):
    adjacency, vertex = make_adjacency(len(prereq), prereq)
    g = Graph()
    g.populate_graph(adjacency)
    is_cycle, path, timestamp = g.dfs_forest()
    if not is_cycle:
        sorted_nodes = sorted(timestamp, key=timestamp.get)
        topological_order = [node.data for node in sorted_nodes]
        return {"is_cycle": False, "topological_order": topological_order}
    else:
        return {"is_cycle": True, "topological_order": []}

