        return random.randint(1, 6)

    # Function to simulate a roll in Fifty
    def executeRoll_fifty(playerScore):
        dieOne = rollDie()
        dieTwo = rollDie()
        if dieOne == dieTwo:
            if dieOne == 3:
                playerScore = 0
            elif dieOne == 6:
                playerScore += 25
            else:
                playerScore += 5
        return playerScore

    # Function to simulate a roll in Pig
    def executeRoll_pig(playerScore):
        dieResult = rollDie()
        if dieResult == 1:
            if playerScore == 0:
                playerScore = -1
            else:
                playerScore = 0
        else:
            playerScore += dieResult
        return playerScore

    # Function to simulate a player's turn in Fifty
    def playerTurn_fifty(playerScore):
        return executeRoll_fifty(playerScore)

    # Function to simulate a player's turn in Pig
    def playerTurn_pig(playerScore, winningScore):
        while True:
            playerScore = executeRoll_pig(playerScore)
            if playerScore == -1 or playerScore >= winningScore:
                break
        return playerScore

    # Simulate the game based on the game_choice
    if game_choice == "Fifty":
