# import necessary packages
import numpy as np

# all class and function definitions in the code file, if any
class AdjacencyMatrixGraph:
    def __init__(self, n):
        self.mapping = {}
        self.graph = np.zeros([n, n])
        self.vertexList = []

    def adjacent(self, x, y):
        xIndex = self.get_vertex_index(x)
        yIndex = self.get_vertex_index(y)
        return bool(self.graph[xIndex, yIndex])

    def neighbors(self, x):
        xIndex = self.get_vertex_index(x)
        neighborIndexes = self.graph[xIndex, :]
        return [self.vertexList[i] for i, val in enumerate(neighborIndexes) if val != 0]

    def add_edge(self, x, y):
        source = self.get_vertex_index(x)
        destination = self.get_vertex_index(y)
        self.graph[source, destination] = 1

    def remove_edge(self, x, y):
        source = self.get_vertex_index(x)
        destination = self.get_vertex_index(y)
        self.graph[source, destination] = 0

    def add_vertex(self, x):
        self.vertexList.append(x)

    def get_vertex_index(self, x):
        for index, value in enumerate(self.vertexList):
            if value == x:
                return index
        return -1

# main function
def main_solution(vertices, edges):
    """
    vertices: list of strings, each string represents a vertex in the graph.
    edges: list of tuples, each tuple represents an edge between two vertices.
