    # Create a graph with the given vertices
    graph = AdjacencyMatrixGraph(len(vertices))
    for vertex in vertices:
        graph.add_vertex(vertex)

    # Add edges to the graph
    for edge in edges:
        graph.add_edge(edge[0], edge[1])

    # Check if the first edge exists in the graph
    if edges:
        result = graph.adjacent(edges[0][0], edges[0][1])
    else:
        result = False

    # Return the result
    return result
