# import necessary packages
from typing import List, Tuple, Union
import random

# all class and function definitions in the code file, if any
class Span:
    def __init__(self, start_idx: int, end_idx: int, label: Union[str, int, list] = "DEFAULT_SPAN", is_parent: bool = False, parent: "Span" = None, confidence: float = None):
        self.start_idx, self.end_idx = start_idx, end_idx
        self.label = label
        self.is_parent = is_parent
        self.parent = parent
        self._children = []
        self.confidence = confidence

    def add_child(self, span: "Span"):
        assert self.is_parent
        span.parent = self
        self._children.append(span)

    def to_json(self) -> dict:
        ret = {
            "label": self.label,
            "span": [self.start_idx, self.end_idx],
        }
        if self.confidence is not None:
            ret['confidence'] = self.confidence
        if self.is_parent:
            children = [child.to_json() for child in self._children]
            ret['children'] = children
        return ret

    @classmethod
    def from_json(cls, span_json: dict) -> "Span":
        span = Span(
            span_json['span'][0], span_json['span'][1], span_json.get('label', None), 'children' in span_json,
            confidence=span_json.get('confidence', None)
        )
        for child_dict in span_json.get('children', []):
            span.add_child(Span.from_json(child_dict))
        return span

# main function
def main_solution(spans_json: List[dict]) -> List[dict]:
    """
    Converts a list of span JSON objects into a list of Span objects, processes them, and then converts them back to JSON format.

    :param spans_json: A list of span JSON objects.
    :return: A list of processed span JSON objects.
    """
    spans = [Span.from_json(span_json) for span_json in spans_json]

    # Example processing: Add a child to each span
    for span in spans:
        if span.is_parent:
            child_span = Span(span.start_idx + 1, span.end_idx + 1, label="CHILD", is_parent=False)
            span.add_child(child_span)

    # Convert back to JSON
    processed_spans_json = [span.to_json() for span in spans]

    return processed_spans_json
